-- ===================== 20261030000017_page_access.sql =====================

-- =====================================================================
--  نظام مخيم 2: الصفحات التي يحددها المدير لكل شخص (للاطلاع)
-- =====================================================================
-- employees.pages: the pages the manager opened for this person to LOOK at (generation,
-- distribution, tasks, attendance, stock). Changing anything stays with the role's own rules.

alter table public.employees add column if not exists pages text[] not null default '{}';

create or replace function public.has_page(p_page text) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_manager() or exists (
    select 1 from public.employees e
     where e.id = public.current_employee_id() and e.is_active and p_page = any (e.pages)
  )
$$;

create or replace function public.admin_set_pages(p_id uuid, p_pages text[]) returns void
language plpgsql security definer set search_path = public as $$
declare v text[];
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  select coalesce(array_agg(distinct x order by x), '{}') into v
    from unnest(coalesce(p_pages, '{}')) as x
   where x in ('generation', 'distribution', 'tasks', 'attendance', 'stock');
  update public.employees set pages = v where id = p_id;
  if not found then raise exception 'missing'; end if;
end $$;

revoke execute on function public.has_page(text), public.admin_set_pages(uuid, text[]) from anon, public;
grant execute on function public.has_page(text), public.admin_set_pages(uuid, text[]) to authenticated;

-- Reading only: the people who were given the page may read its data, on top of what the role
-- already allows (the existing rule of each policy is kept and one more way in is added).
do $$
declare r record; q text;
begin
  for r in
    select * from (values
      ('site_reports', 'site_reports_read', 'generation'),
      ('site_report_fuel', 'site_report_fuel_read', 'generation'),
      ('generator_day_logs', 'generator_day_logs_read', 'generation'),
      ('generator_runs', 'generator_runs_read', 'generation'),
      ('maintenance_logs', 'maintenance_logs_read', 'generation'),
      ('distribution_sheets', 'distribution_sheets_read', 'distribution'),
      ('zone_day_entries', 'zone_day_entries_read', 'distribution'),
      ('zone_runs', 'zone_runs_read', 'distribution'),
      ('tasks', 'tasks_read', 'tasks'),
      ('task_events', 'task_events_read', 'tasks'),
      ('attendance_punches', 'attendance_punches_read', 'attendance'),
      ('leaves', 'leaves_read', 'attendance')
    ) as t (tbl, pol, page)
  loop
    select qual into q from pg_policies where schemaname = 'public' and tablename = r.tbl and policyname = r.pol;
    if q is null then raise exception 'policy % on % not found', r.pol, r.tbl; end if;
    if position('has_page' in q) = 0 then
      execute format('alter policy %I on public.%I using ((%s) or public.has_page(%L))', r.pol, r.tbl, q, r.page);
    end if;
  end loop;
end $$;

drop policy if exists stock_moves_read on public.stock_moves;
create policy stock_moves_read on public.stock_moves for select to authenticated using (public.has_page('stock'));

notify pgrst, 'reload schema';

-- ===================== 20261030000018_employee_trash.sql =====================

-- =====================================================================
--  نظام مخيم 2: حذف موظف (سلة المهملات) لمدير الفرع فقط
-- =====================================================================
-- The branch manager (role «manager», not the admin) can delete a person: they leave every list and
-- cannot sign in, but nothing they did is lost, and they wait in the trash to be brought back.

alter table public.employees add column if not exists deleted_at timestamptz;

create or replace function public.admin_delete_employee(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_role public.user_role; v_user uuid;
begin
  if public.current_user_role() is distinct from 'manager' then raise exception 'not_allowed' using errcode = '42501'; end if;
  if p_id = public.current_employee_id() then raise exception 'self'; end if;
  select role, auth_user_id into v_role, v_user from public.employees where id = p_id and deleted_at is null;
  if not found then raise exception 'missing'; end if;
  if v_role in ('admin', 'manager') then raise exception 'protected'; end if;
  update public.employees set deleted_at = now(), is_active = false where id = p_id;
  if v_user is not null then delete from auth.sessions where user_id = v_user; end if;
end $$;

create or replace function public.admin_restore_employee(p_id uuid) returns void
language plpgsql security definer set search_path = public as $$
begin
  if public.current_user_role() is distinct from 'manager' then raise exception 'not_allowed' using errcode = '42501'; end if;
  update public.employees set deleted_at = null, is_active = true where id = p_id and deleted_at is not null;
  if not found then raise exception 'missing'; end if;
end $$;

revoke execute on function public.admin_delete_employee(uuid), public.admin_restore_employee(uuid) from anon, public;
grant execute on function public.admin_delete_employee(uuid), public.admin_restore_employee(uuid) to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000019_seals_unnamed_batch.sql =====================

-- =====================================================================
--  نظام مخيم 2: الأختام - تجهيز دفعة بدون اسم، وتعيين الاسم لاحقاً
-- =====================================================================
-- The accountant first prepares the seals of a batch, then says who takes them. Until then the
-- batch has no technician («بدون اسم»); nothing can be recorded as used on it.

alter table public.seal_batches alter column technician_id drop not null;

create or replace function public.seal_issue(p_technician uuid, p_issued_on date, p_seals integer[], p_note text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := public.current_employee_id();
  v_n integer := coalesce(array_length(p_seals, 1), 0);
  v_roll uuid;
  v_rolls integer;
  v_bad integer;
  v_batch uuid;
  v_no integer;
begin
  if not public.has_seals() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if v_n = 0 or v_n > 100 then raise exception 'no_seals'; end if;
  if (select count(distinct x) from unnest(p_seals) x) <> v_n then raise exception 'duplicate_seal'; end if;
  -- The name can wait: a prepared batch has none until the accountant picks one.
  if p_technician is not null and not exists (select 1 from public.employees where id = p_technician and role = 'technician' and is_active) then
    raise exception 'bad_technician';
  end if;
  if p_issued_on is null or p_issued_on > public.seal_today() + 1 then raise exception 'bad_date'; end if;

  perform 1 from public.seals where seal_no = any (p_seals) order by seal_no for update;
  select x into v_bad from unnest(p_seals) x where not exists (select 1 from public.seals s where s.seal_no = x) limit 1;
  if v_bad is not null then raise exception 'unknown_seal:%', v_bad; end if;
  select s.seal_no into v_bad from public.seals s where s.seal_no = any (p_seals) and s.status <> 'in_stock' order by s.seal_no limit 1;
  if v_bad is not null then raise exception 'not_available:%', v_bad; end if;
  select count(distinct roll_id), min(roll_id::text)::uuid into v_rolls, v_roll from public.seals where seal_no = any (p_seals);
  if v_rolls > 1 then raise exception 'mixed_rolls'; end if;

  select coalesce(max(batch_no), 0) + 1 into v_no from public.seal_batches where roll_id = v_roll;
  insert into public.seal_batches (roll_id, batch_no, technician_id, issued_on, note, created_by)
    values (v_roll, v_no, p_technician, p_issued_on, nullif(btrim(coalesce(p_note, '')), ''), v_me)
    returning id into v_batch;
  update public.seals s
     set status = 'issued', batch_id = v_batch, batch_pos = o.pos, technician_id = p_technician,
         issued_on = p_issued_on, used_on = null, details = null, board_no = null, updated_by = v_me
    from unnest(p_seals) with ordinality as o (no, pos)
   where s.seal_no = o.no;
  return jsonb_build_object('batch_id', v_batch, 'batch_no', v_no, 'roll_id', v_roll, 'count', v_n);
end $$;


-- Gives a prepared batch its name (a named batch is changed with seal_update_batch).
create or replace function public.seal_assign_batch(p_batch uuid, p_technician uuid) returns void
language plpgsql security definer set search_path = public as $$
declare v_me uuid := public.current_employee_id();
begin
  if not public.has_seals() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if not exists (select 1 from public.employees where id = p_technician and role = 'technician' and is_active) then raise exception 'bad_technician'; end if;
  update public.seal_batches set technician_id = p_technician where id = p_batch;
  if not found then raise exception 'missing'; end if;
  update public.seals set technician_id = p_technician, updated_by = v_me where batch_id = p_batch;
end $$;

revoke execute on function public.seal_issue(uuid, date, integer[], text), public.seal_assign_batch(uuid, uuid) from anon, public;
grant execute on function public.seal_issue(uuid, date, integer[], text), public.seal_assign_batch(uuid, uuid) to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000020_seals_live.sql =====================

-- =====================================================================
--  نظام مخيم 2: الأختام - ما تعمله محاسن يظهر عند علياء فوراً
-- =====================================================================
-- Puts the three seals tables on the project's change feed (Realtime), so every screen with the
-- seals open hears of a change at once. Nothing happens on a project without Realtime.

do $$
declare t text;
begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime') then
    foreach t in array array['seals', 'seal_batches', 'seal_rolls'] loop
      if not exists (
        select 1 from pg_publication_tables where pubname = 'supabase_realtime' and schemaname = 'public' and tablename = t
      ) then
        execute format('alter publication supabase_realtime add table public.%I', t);
      end if;
    end loop;
  end if;
end $$;

notify pgrst, 'reload schema';

-- ===================== 20261030000021_seals_add_to_batch.sql =====================

-- =====================================================================
--  نظام مخيم 2: الأختام · إضافة أختام جديدة لدفعة موجودة (من «تعديل»)
-- =====================================================================
-- The new seals must be in stock and from the batch's own roll; they take its technician and day.

create or replace function public.seal_add_to_batch(p_batch uuid, p_seals integer[]) returns integer
language plpgsql security definer set search_path = public as $$
declare
  v_me uuid := public.current_employee_id();
  v_n integer := coalesce(array_length(p_seals, 1), 0);
  v_b public.seal_batches;
  v_bad integer;
  v_pos integer;
begin
  if not public.has_seals() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if v_n = 0 or v_n > 100 then raise exception 'no_seals'; end if;
  if (select count(distinct x) from unnest(p_seals) x) <> v_n then raise exception 'duplicate_seal'; end if;
  select * into v_b from public.seal_batches where id = p_batch for update;
  if not found then raise exception 'missing'; end if;

  perform 1 from public.seals where seal_no = any (p_seals) order by seal_no for update;
  select x into v_bad from unnest(p_seals) x where not exists (select 1 from public.seals s where s.seal_no = x) limit 1;
  if v_bad is not null then raise exception 'unknown_seal:%', v_bad; end if;
  select s.seal_no into v_bad from public.seals s where s.seal_no = any (p_seals) and s.status <> 'in_stock' order by s.seal_no limit 1;
  if v_bad is not null then raise exception 'not_available:%', v_bad; end if;
  if exists (select 1 from public.seals where seal_no = any (p_seals) and roll_id <> v_b.roll_id) then raise exception 'mixed_rolls'; end if;

  select coalesce(max(batch_pos), 0) into v_pos from public.seals where batch_id = p_batch;
  update public.seals s
     set status = 'issued', batch_id = p_batch, batch_pos = v_pos + o.pos, technician_id = v_b.technician_id,
         issued_on = v_b.issued_on, used_on = null, details = null, board_no = null, updated_by = v_me
    from unnest(p_seals) with ordinality as o (no, pos)
   where s.seal_no = o.no;
  update public.seal_batches set original_seals = null where id = p_batch;
  return v_n;
end $$;

revoke execute on function public.seal_add_to_batch(uuid, integer[]) from anon, public;
grant execute on function public.seal_add_to_batch(uuid, integer[]) to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000022_seal_work_statement.sql =====================

-- =====================================================================
--  نظام مخيم 2: كشف أعمال الفنيين بالأختام (صفحة المهام والتقارير)
-- =====================================================================
-- The seals a technician used, with the day and the work written. Open to those who may see the
-- tasks or the reports as well as to the seals office, without opening the seals tables themselves.

create or replace function public.seal_work_statement(p_from date, p_to date)
returns table (seal_no integer, technician_id uuid, used_on date, issued_on date, details text, board_no text)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.is_manager() or public.has_seals() or public.has_page('tasks') or public.has_page('reports')) then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  return query
    select s.seal_no, s.technician_id, s.used_on, s.issued_on, s.details, s.board_no
      from public.seals s
     where s.status = 'used' and s.technician_id is not null
       and coalesce(s.used_on, s.issued_on) between coalesce(p_from, date '2000-01-01') and coalesce(p_to, date '2999-12-31')
     order by coalesce(s.used_on, s.issued_on), s.seal_no;
end $$;

revoke execute on function public.seal_work_statement(date, date) from anon, public;
grant execute on function public.seal_work_statement(date, date) to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000023_attendance_place_and_limits.sql =====================

-- =====================================================================
--  نظام مخيم 2: الحضور بالـQR · موقع المكتب، مرتين باليوم، ومدة بين الحضور والانصراف
-- =====================================================================
-- 1. The office place (set by the manager from the phone standing in the office) and a radius: a scan
--    from farther away is refused.
-- 2. At most two scans a day for a person (one arrival, one departure).
-- 3. The departure cannot come before 60 minutes after the arrival (a refreshed page or a second
--    look at the sheet never ends the day by accident).
-- 4. «Peek»: the page can ask for today's record without recording anything.

alter table public.attendance_points add column if not exists lat double precision;
alter table public.attendance_points add column if not exists lng double precision;
alter table public.attendance_points add column if not exists radius_m integer not null default 100;
alter table public.attendance_points drop constraint if exists attendance_points_place_ok;
alter table public.attendance_points add constraint attendance_points_place_ok
  check ((lat is null and lng is null) or (lat between -90 and 90 and lng between -180 and 180 and radius_m between 20 and 1000));

-- Metres between two points on the earth (haversine).
create or replace function public.distance_m(lat1 double precision, lng1 double precision, lat2 double precision, lng2 double precision) returns double precision
language sql immutable as $$
  select 2 * 6371000 * asin(sqrt(
    power(sin(radians(lat2 - lat1) / 2), 2) + cos(radians(lat1)) * cos(radians(lat2)) * power(sin(radians(lng2 - lng1) / 2), 2)
  ))
$$;

drop function if exists public.attendance_punch(text, text);
create or replace function public.attendance_punch(
  p_point text, p_token text,
  p_lat double precision default null, p_lng double precision default null, p_acc double precision default null,
  p_peek boolean default false
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_point smallint := public.attendance_point_id(p_point);
  pt public.attendance_points;
  d public.attendance_devices;
  e public.employees;
  v_last public.attendance_punches;
  v_kind public.punch_kind;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Asia/Gaza')) at time zone 'Asia/Gaza';
  v_stay constant interval := interval '60 minutes';
  v_dist double precision;
  v_scans integer;
  v_status text := 'recorded';
  v_wait timestamptz;
begin
  if v_point is null then raise exception 'bad_point'; end if;
  select * into pt from public.attendance_points where id = v_point;
  select * into d from public.attendance_devices
    where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex') and revoked_at is null;
  if not found then raise exception 'unknown_device'; end if;
  select * into e from public.employees where id = d.employee_id;
  if not (e.is_active and e.tracks_attendance) then raise exception 'not_tracked'; end if;

  -- Only from the office, when the manager has set where it is. The phone's own accuracy is allowed for (up to 50 m).
  if not p_peek and pt.lat is not null then
    if p_lat is null or p_lng is null then raise exception 'need_location'; end if;
    v_dist := public.distance_m(pt.lat, pt.lng, p_lat, p_lng);
    if v_dist - least(greatest(coalesce(p_acc, 0), 0), 50) > pt.radius_m then
      raise exception 'too_far:%', round(v_dist);
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtext(e.id::text));
  select * into v_last from public.attendance_punches
    where employee_id = e.id and at >= v_day_start order by at desc limit 1;
  select count(*) into v_scans from public.attendance_punches
    where employee_id = e.id and at >= v_day_start and method = 'qr';

  if found and v_last.kind = 'in' then v_kind := 'out'; else v_kind := 'in'; end if;
  if v_scans >= 2 then
    v_status := 'full';
  elsif v_last.at is not null and v_last.at > now() - interval '2 minutes' then
    v_status := 'repeat';
  elsif v_kind = 'out' and v_last.at > now() - v_stay then
    v_status := 'wait';
    v_wait := v_last.at + v_stay;
  end if;

  if v_status = 'recorded' and not p_peek then
    insert into public.attendance_punches (employee_id, kind, at, method, point_id)
      values (e.id, v_kind, now(), 'qr', v_point);
  elsif v_status = 'recorded' then
    v_status := 'ready';
  end if;
  if not p_peek then update public.attendance_devices set last_used_at = now() where id = d.id; end if;

  return jsonb_build_object(
    'name', e.full_name,
    'repeat', v_status = 'repeat',
    'status', v_status,
    'next', v_kind,
    'wait_until', v_wait,
    'punches', coalesce((
      select jsonb_agg(jsonb_build_object('kind', p.kind, 'at', p.at) order by p.at)
      from public.attendance_punches p where p.employee_id = e.id and p.at >= v_day_start), '[]'::jsonb)
  );
end $$;

revoke execute on function public.attendance_punch(text, text, double precision, double precision, double precision, boolean) from public;
grant execute on function public.attendance_punch(text, text, double precision, double precision, double precision, boolean) to anon, authenticated;
revoke execute on function public.distance_m(double precision, double precision, double precision, double precision) from public;
grant execute on function public.distance_m(double precision, double precision, double precision, double precision) to anon, authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000024_seal_work_page.sql =====================

-- =====================================================================
--  نظام مخيم 2: صلاحية مستقلة لكشف أعمال الأختام، يفتحها المدير لمن يختار
-- =====================================================================
-- Keeps existing task/report summaries working; grants statement-only readers no seals editing access.
-- No existing employee is granted a new page automatically. Safe to apply more than once.

create or replace function public.admin_set_pages(p_id uuid, p_pages text[]) returns void
language plpgsql security definer set search_path = public as $$
declare v text[];
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  select coalesce(array_agg(distinct x order by x), '{}') into v
    from unnest(coalesce(p_pages, '{}')) as x
   where x in ('generation', 'distribution', 'tasks', 'attendance', 'stock', 'seal-work');
  update public.employees set pages = v where id = p_id;
  if not found then raise exception 'missing'; end if;
end $$;

revoke execute on function public.has_page(text), public.admin_set_pages(uuid, text[]) from anon, public;
grant execute on function public.has_page(text), public.admin_set_pages(uuid, text[]) to authenticated;


create or replace function public.seal_work_statement(p_from date, p_to date)
returns table (seal_no integer, technician_id uuid, used_on date, issued_on date, details text, board_no text)
language plpgsql stable security definer set search_path = public as $$
begin
  if not (public.is_manager() or public.has_seals() or public.has_page('tasks') or public.has_page('reports') or public.has_page('seal-work')) then
    raise exception 'not_allowed' using errcode = '42501';
  end if;
  return query
    select s.seal_no, s.technician_id, s.used_on, s.issued_on, s.details, s.board_no
      from public.seals s
     where s.status = 'used' and s.technician_id is not null
       and coalesce(s.used_on, s.issued_on) between coalesce(p_from, date '2000-01-01') and coalesce(p_to, date '2999-12-31')
     order by coalesce(s.used_on, s.issued_on), s.seal_no;
end $$;

revoke execute on function public.seal_work_statement(date, date) from anon, public;
grant execute on function public.seal_work_statement(date, date) to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000025_task_intake.sql =====================

-- =====================================================================
--  نظام مخيم 2: تجهيز مهمة (اتصال المشترك يُسجَّل قبل اختيار الفني)
-- =====================================================================
-- A call is written down at once (who, what, where, phone) with no technician yet; later it is
-- given to a technician and sent by WhatsApp or SMS like any task. Whoever has the tasks page may
-- prepare, give and send tasks, not only managers. Safe to apply more than once.

alter table public.tasks alter column assignee_id drop not null;

create or replace function public.tasks_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  acting uuid := nullif(current_setting('m2.acting_employee', true), '')::uuid;
  me uuid := coalesce(acting, public.current_employee_id());
  mgr boolean := acting is null and (public.is_manager() or public.has_page('tasks'));
  t timestamptz;
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(me, new.created_by);
    new.status := 'new';
    new.sent_at := null; new.seen_at := null; new.started_at := null;
    new.completed_at := null; new.cancelled_at := null;
    return new;
  end if;

  if not mgr then
    if me is null or old.assignee_id is distinct from me then
      raise exception 'This task is not assigned to you';
    end if;
    if (new.task_type_id, new.assignee_id, new.details, new.subscriber_name, new.subscriber_phone,
        new.zone_id, new.location_text, new.priority, new.expected_minutes, new.created_by, new.cancel_reason, new.link_token)
       is distinct from
       (old.task_type_id, old.assignee_id, old.details, old.subscriber_name, old.subscriber_phone,
        old.zone_id, old.location_text, old.priority, old.expected_minutes, old.created_by, old.cancel_reason, old.link_token) then
      raise exception 'A technician can only start, finish and add notes to a task';
    end if;
    if new.status is distinct from old.status and not (
         (old.status in ('new', 'sent') and new.status = 'seen')
      or (old.status in ('new', 'sent', 'seen') and new.status = 'in_progress')
      or (old.status = 'in_progress' and new.status = 'done')) then
      raise exception 'Invalid task step';
    end if;
  else
    if new.assignee_id is distinct from old.assignee_id then
      if old.status not in ('new', 'sent', 'seen') then
        raise exception 'A started or closed task cannot be reassigned';
      end if;
      new.status := 'new';
      new.sent_at := null; new.seen_at := null;
      insert into public.task_events (task_id, event, actor_id, meta)
        values (new.id, 'reassigned', me, jsonb_build_object('from', old.assignee_id, 'to', new.assignee_id));
    elsif new.status is distinct from old.status and not (
         (old.status = 'new' and new.status = 'sent')
      or (old.status in ('new', 'sent', 'seen', 'in_progress') and new.status = 'cancelled')) then
      raise exception 'The manager can send or cancel a task; the technician starts and finishes it';
    end if;
  end if;

  -- Server-owned times: copied from the old row unless this update is the step that sets them.
  new.sent_at := coalesce(new.sent_at, old.sent_at);
  if new.assignee_id is not distinct from old.assignee_id then
    new.sent_at := old.sent_at; new.seen_at := old.seen_at;
  end if;
  new.started_at := old.started_at; new.completed_at := old.completed_at; new.cancelled_at := old.cancelled_at;

  if new.status is distinct from old.status then
    t := public.event_time(new.recorded_offline, new.device_time, coalesce(old.started_at, old.sent_at, old.created_at));
    case new.status
      when 'sent' then
        new.sent_at := now();
      when 'seen' then
        new.seen_at := t;
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'seen', me, t, new.recorded_offline);
      when 'in_progress' then
        new.seen_at := coalesce(new.seen_at, t);
        new.started_at := t;
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'started', me, t, new.recorded_offline);
      when 'done' then
        new.completed_at := greatest(t, new.started_at);
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'completed', me, new.completed_at, new.recorded_offline);
      when 'cancelled' then
        if length(btrim(coalesce(new.cancel_reason, ''))) = 0 then
          raise exception 'Cancelling a task needs a reason';
        end if;
        new.cancelled_at := now();
        insert into public.task_events (task_id, event, actor_id) values (new.id, 'cancelled', me);
      else
        null;
    end case;
  end if;
  return new;
end $$;

drop policy if exists tasks_insert on public.tasks;
create policy tasks_insert on public.tasks for insert to authenticated
  with check (public.is_manager() or public.has_page('tasks'));
drop policy if exists tasks_update on public.tasks;
create policy tasks_update on public.tasks for update to authenticated
  using (public.is_manager() or public.has_page('tasks') or assignee_id = public.current_employee_id())
  with check (public.is_manager() or public.has_page('tasks') or assignee_id = public.current_employee_id());
drop policy if exists outgoing_messages_manage on public.outgoing_messages;
create policy outgoing_messages_manage on public.outgoing_messages for all to authenticated
  using (public.is_manager() or public.has_page('tasks')) with check (public.is_manager() or public.has_page('tasks'));

notify pgrst, 'reload schema';

-- ===================== 20261030000026_zone_extra_loads.sql =====================

-- =====================================================================
--  نظام مخيم 2: قراءات أحمال إضافية بالتوزيع (أكثر من L1 L2 L3)
-- =====================================================================
-- The site may read as many loads as it needs for a run; they count in the run's average.

alter table public.zone_runs add column if not exists load_extra numeric[] not null default '{}';
alter table public.zone_runs drop constraint if exists zone_runs_load_extra_ok;
alter table public.zone_runs add constraint zone_runs_load_extra_ok
  check (cardinality(load_extra) <= 30 and 0 <= all (load_extra));

notify pgrst, 'reload schema';

-- ===================== 20261030000027_subscribers.sql =====================

-- =====================================================================
--  نظام مخيم 2: دليل المشتركين (الاسم، المنطقة، الطبلون، الجوال) لتعبئة المهام بسرعة
-- =====================================================================
-- Read by whoever has the tasks page; replaced as a whole from the office's Excel by a manager.

create table if not exists public.subscribers (
  id bigint generated always as identity primary key,
  full_name text not null check (length(btrim(full_name)) between 2 and 120),
  area text,
  board text,
  phone text,
  created_at timestamptz not null default now()
);
alter table public.subscribers enable row level security;
drop policy if exists subscribers_read on public.subscribers;
create policy subscribers_read on public.subscribers for select to authenticated
  using (public.is_manager() or public.has_page('tasks') or public.has_seals());
revoke all on public.subscribers from anon;
grant select on public.subscribers to authenticated;

-- The whole list at once: [{"n": name, "a": area, "b": board, "p": phone}, ...]
create or replace function public.subscribers_import(p jsonb) returns integer
language plpgsql security definer set search_path = public as $$
declare v integer;
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if jsonb_typeof(p) <> 'array' then raise exception 'bad_file'; end if;
  delete from public.subscribers where true;
  insert into public.subscribers (full_name, area, board, phone)
  select btrim(x ->> 'n'), nullif(btrim(x ->> 'a'), ''), nullif(btrim(x ->> 'b'), ''), nullif(regexp_replace(coalesce(x ->> 'p', ''), '[^0-9]', '', 'g'), '')
    from jsonb_array_elements(p) x
   where length(btrim(coalesce(x ->> 'n', ''))) between 2 and 120;
  get diagnostics v = row_count;
  return v;
end $$;
revoke execute on function public.subscribers_import(jsonb) from anon, public;
grant execute on function public.subscribers_import(jsonb) to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000028_task_done_by_office.sql =====================

-- =====================================================================
--  نظام مخيم 2: «تم الإنجاز» من المكتب لفني ما عنده جوال ذكي
-- =====================================================================
-- Whoever runs the tasks (manager, or the tasks page) can mark a technician's task done; the time is
-- the moment it is marked (or, when marked without internet, the moment on the phone).

create or replace function public.tasks_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  acting uuid := nullif(current_setting('m2.acting_employee', true), '')::uuid;
  me uuid := coalesce(acting, public.current_employee_id());
  mgr boolean := acting is null and (public.is_manager() or public.has_page('tasks'));
  t timestamptz;
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(me, new.created_by);
    new.status := 'new';
    new.sent_at := null; new.seen_at := null; new.started_at := null;
    new.completed_at := null; new.cancelled_at := null;
    return new;
  end if;

  if not mgr then
    if me is null or old.assignee_id is distinct from me then
      raise exception 'This task is not assigned to you';
    end if;
    if (new.task_type_id, new.assignee_id, new.details, new.subscriber_name, new.subscriber_phone,
        new.zone_id, new.location_text, new.priority, new.expected_minutes, new.created_by, new.cancel_reason, new.link_token)
       is distinct from
       (old.task_type_id, old.assignee_id, old.details, old.subscriber_name, old.subscriber_phone,
        old.zone_id, old.location_text, old.priority, old.expected_minutes, old.created_by, old.cancel_reason, old.link_token) then
      raise exception 'A technician can only start, finish and add notes to a task';
    end if;
    if new.status is distinct from old.status and not (
         (old.status in ('new', 'sent') and new.status = 'seen')
      or (old.status in ('new', 'sent', 'seen') and new.status = 'in_progress')
      or (old.status = 'in_progress' and new.status = 'done')) then
      raise exception 'Invalid task step';
    end if;
  else
    if new.assignee_id is distinct from old.assignee_id then
      if old.status not in ('new', 'sent', 'seen') then
        raise exception 'A started or closed task cannot be reassigned';
      end if;
      new.status := 'new';
      new.sent_at := null; new.seen_at := null;
      insert into public.task_events (task_id, event, actor_id, meta)
        values (new.id, 'reassigned', me, jsonb_build_object('from', old.assignee_id, 'to', new.assignee_id));
    elsif new.status is distinct from old.status and not (
         (old.status = 'new' and new.status = 'sent')
      or (old.status in ('new', 'sent', 'seen', 'in_progress') and new.status = 'cancelled')
      -- A technician without a smartphone: the office marks the task done for him.
      or (old.status in ('new', 'sent', 'seen', 'in_progress') and new.status = 'done' and new.assignee_id is not null)) then
      raise exception 'The manager can send or cancel a task; the technician starts and finishes it';
    end if;
  end if;

  -- Server-owned times: copied from the old row unless this update is the step that sets them.
  new.sent_at := coalesce(new.sent_at, old.sent_at);
  if new.assignee_id is not distinct from old.assignee_id then
    new.sent_at := old.sent_at; new.seen_at := old.seen_at;
  end if;
  new.started_at := old.started_at; new.completed_at := old.completed_at; new.cancelled_at := old.cancelled_at;

  if new.status is distinct from old.status then
    t := public.event_time(new.recorded_offline, new.device_time, coalesce(old.started_at, old.sent_at, old.created_at));
    case new.status
      when 'sent' then
        new.sent_at := now();
      when 'seen' then
        new.seen_at := t;
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'seen', me, t, new.recorded_offline);
      when 'in_progress' then
        new.seen_at := coalesce(new.seen_at, t);
        new.started_at := t;
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'started', me, t, new.recorded_offline);
      when 'done' then
        new.started_at := coalesce(new.started_at, least(t, coalesce(old.seen_at, old.sent_at, t)));
        new.completed_at := greatest(t, new.started_at);
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'completed', me, new.completed_at, new.recorded_offline);
      when 'cancelled' then
        if length(btrim(coalesce(new.cancel_reason, ''))) = 0 then
          raise exception 'Cancelling a task needs a reason';
        end if;
        new.cancelled_at := now();
        insert into public.task_events (task_id, event, actor_id) values (new.id, 'cancelled', me);
      else
        null;
    end case;
  end if;
  return new;
end $$;


notify pgrst, 'reload schema';

-- ===================== 20261030000029_meter_readings.sql =====================

-- =====================================================================
--  نظام مخيم 2: القراءات الأسبوعية (قراءات عدادات المشتركين)
-- =====================================================================
-- A batch per week from the company's Excel file. Each subscriber row keeps its place in the file;
-- an area goes either to a reader in the app or to a paper sheet. Readers enter readings on the
-- phone (also without internet); the reading admin reviews and exports the same file filled in.

create table if not exists public.reading_batches (
  id uuid primary key default gen_random_uuid(),
  title text not null,
  period_from date,
  period_to date,
  file_name text,
  -- The original file (base64), so the export keeps its sheets, order and formats.
  source_b64 text,
  sheet_name text,
  -- Which column (1-based) gets the current reading in the export.
  current_col integer,
  status text not null default 'open' check (status in ('open', 'approved')),
  created_by uuid references public.employees (id),
  created_at timestamptz not null default now()
);

create table if not exists public.reading_rows (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.reading_batches (id) on delete cascade,
  ord integer not null,
  sheet_row integer not null,
  code text not null default '',
  area text not null default '',
  board text not null default '',
  fak text,
  subscriber text not null default '',
  phone text,
  prev numeric,
  -- How the area is read this week: by a reader in the app, or on a paper sheet.
  mode text check (mode in ('app', 'paper')),
  assignee_id uuid references public.employees (id),
  reading numeric,
  state text check (state in ('disconnected', 'no_meter', 'other', 'unknown')),
  note text,
  source text check (source in ('app', 'paper')),
  entered_by uuid references public.employees (id),
  entered_at timestamptz,
  updated_at timestamptz not null default now(),
  unique (batch_id, ord),
  check (reading is null or state is null),
  check (reading is null or prev is null or reading >= prev)
);
create index if not exists reading_rows_assignee on public.reading_rows (assignee_id, batch_id);
create index if not exists reading_rows_batch on public.reading_rows (batch_id, area, board, ord);

-- Who runs the readings: managers, or whoever was given «مسؤول القراءات».
create or replace function public.is_reading_admin() returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_manager() or public.has_page('readings-admin')
$$;

alter table public.reading_batches enable row level security;
alter table public.reading_rows enable row level security;
drop policy if exists reading_batches_read on public.reading_batches;
create policy reading_batches_read on public.reading_batches for select to authenticated
  using (public.is_reading_admin() or exists (select 1 from public.reading_rows r where r.batch_id = id and r.assignee_id = public.current_employee_id()));
drop policy if exists reading_batches_admin on public.reading_batches;
create policy reading_batches_admin on public.reading_batches for all to authenticated
  using (public.is_reading_admin()) with check (public.is_reading_admin());
drop policy if exists reading_rows_read on public.reading_rows;
create policy reading_rows_read on public.reading_rows for select to authenticated
  using (public.is_reading_admin() or assignee_id = public.current_employee_id());
drop policy if exists reading_rows_insert on public.reading_rows;
create policy reading_rows_insert on public.reading_rows for insert to authenticated with check (public.is_reading_admin());
drop policy if exists reading_rows_delete on public.reading_rows;
create policy reading_rows_delete on public.reading_rows for delete to authenticated using (public.is_reading_admin());
drop policy if exists reading_rows_update on public.reading_rows;
create policy reading_rows_update on public.reading_rows for update to authenticated
  using (public.is_reading_admin() or assignee_id = public.current_employee_id())
  with check (public.is_reading_admin() or assignee_id = public.current_employee_id());
revoke all on public.reading_batches, public.reading_rows from anon;
grant select, insert, update, delete on public.reading_batches, public.reading_rows to authenticated;

-- A reader changes only the reading, the state and the note, only on his own rows, only while the batch is open.
create or replace function public.reading_rows_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  me uuid := public.current_employee_id();
  adm boolean := public.is_reading_admin();
begin
  if (select status from public.reading_batches where id = new.batch_id) = 'approved' and not adm then
    raise exception 'batch_closed';
  end if;
  if not adm then
    if old.assignee_id is distinct from me or old.mode is distinct from 'app' then raise exception 'not_yours'; end if;
    if (new.batch_id, new.ord, new.sheet_row, new.code, new.area, new.board, new.fak, new.subscriber, new.phone, new.prev, new.mode, new.assignee_id)
       is distinct from (old.batch_id, old.ord, old.sheet_row, old.code, old.area, old.board, old.fak, old.subscriber, old.phone, old.prev, old.mode, old.assignee_id) then
      raise exception 'not_allowed';
    end if;
    new.source := 'app';
  end if;
  if (new.reading, new.state, new.note) is distinct from (old.reading, old.state, old.note) then
    new.entered_by := me;
    new.entered_at := now();
    if adm and new.source is null then new.source := coalesce(old.mode, 'paper'); end if;
  end if;
  new.updated_at := now();
  return new;
end $$;
drop trigger if exists reading_rows_guard on public.reading_rows;
create trigger reading_rows_guard before update on public.reading_rows for each row execute function public.reading_rows_guard();

-- Who changed what, for the review.
create table if not exists public.reading_changes (
  id bigint generated always as identity primary key,
  row_id uuid not null references public.reading_rows (id) on delete cascade,
  old_reading numeric, new_reading numeric, old_state text, new_state text,
  by_id uuid references public.employees (id), at timestamptz not null default now()
);
alter table public.reading_changes enable row level security;
drop policy if exists reading_changes_read on public.reading_changes;
create policy reading_changes_read on public.reading_changes for select to authenticated using (public.is_reading_admin());
revoke all on public.reading_changes from anon;
grant select on public.reading_changes to authenticated;
create or replace function public.reading_rows_log() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  if (new.reading, new.state) is distinct from (old.reading, old.state) and (old.reading is not null or old.state is not null) then
    insert into public.reading_changes (row_id, old_reading, new_reading, old_state, new_state, by_id)
    values (new.id, old.reading, new.reading, old.state, new.state, public.current_employee_id());
  end if;
  return new;
end $$;
drop trigger if exists reading_rows_log on public.reading_rows;
create trigger reading_rows_log after update on public.reading_rows for each row execute function public.reading_rows_log();

-- The two new pages in «الصلاحيات».
create or replace function public.admin_set_pages(p_id uuid, p_pages text[]) returns void
language plpgsql security definer set search_path = public as $$
declare v text[];
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  select coalesce(array_agg(distinct x order by x), '{}') into v
    from unnest(coalesce(p_pages, '{}')) as x
   where x in ('generation', 'distribution', 'tasks', 'attendance', 'stock', 'seal-work', 'readings', 'readings-admin');
  update public.employees set pages = v where id = p_id;
  if not found then raise exception 'missing'; end if;
end $$;
revoke execute on function public.is_reading_admin(), public.admin_set_pages(uuid, text[]) from anon, public;
grant execute on function public.is_reading_admin(), public.admin_set_pages(uuid, text[]) to authenticated;

do $$ begin
  if exists (select 1 from pg_publication where pubname = 'supabase_realtime')
     and not exists (select 1 from pg_publication_tables where pubname = 'supabase_realtime' and tablename = 'reading_rows') then
    alter publication supabase_realtime add table public.reading_rows;
  end if;
end $$;

notify pgrst, 'reload schema';

-- ===================== 20261030000030_readings_reader_sees_batch.sql =====================

-- =====================================================================
--  نظام مخيم 2: القارئ يشوف كشف القراءات اللي إله فيه مشتركين
-- =====================================================================
-- The reader's rule compared the row with itself (an unqualified «id» inside the subquery):
-- now it names the batch, so a reader sees the week he has subscribers in.

drop policy if exists reading_batches_read on public.reading_batches;
create policy reading_batches_read on public.reading_batches for select to authenticated
  using (public.is_reading_admin() or exists (
    select 1 from public.reading_rows r where r.batch_id = reading_batches.id and r.assignee_id = public.current_employee_id()
  ));

-- ===================== 20261030000031_reading_files.sql =====================

-- =====================================================================
--  نظام مخيم 2: أسبوع القراءات فيه ملفات كثيرة (حوالي 36 كشف بالأسبوع)
-- =====================================================================
-- Each file the office uploads is kept as it came; every subscriber row knows its file and sheet,
-- so the export gives back every file with its own «القراءة الحالية» filled.

create table if not exists public.reading_files (
  id uuid primary key default gen_random_uuid(),
  batch_id uuid not null references public.reading_batches (id) on delete cascade,
  file_name text not null,
  source_b64 text not null,
  current_col integer not null default 4,
  rows_count integer not null default 0,
  created_by uuid references public.employees (id),
  created_at timestamptz not null default now()
);
create index if not exists reading_files_batch on public.reading_files (batch_id, created_at);
alter table public.reading_rows add column if not exists file_id uuid references public.reading_files (id) on delete cascade;
alter table public.reading_rows add column if not exists sheet text;

alter table public.reading_files enable row level security;
drop policy if exists reading_files_admin on public.reading_files;
create policy reading_files_admin on public.reading_files for all to authenticated
  using (public.is_reading_admin()) with check (public.is_reading_admin());
revoke all on public.reading_files from anon;
grant select, insert, update, delete on public.reading_files to authenticated;

-- The reader still changes only the reading, the state and the note (now also never the file or sheet).
create or replace function public.reading_rows_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  me uuid := public.current_employee_id();
  adm boolean := public.is_reading_admin();
begin
  if (select status from public.reading_batches where id = new.batch_id) = 'approved' and not adm then
    raise exception 'batch_closed';
  end if;
  if not adm then
    if old.assignee_id is distinct from me or old.mode is distinct from 'app' then raise exception 'not_yours'; end if;
    if (new.batch_id, new.ord, new.sheet_row, new.code, new.area, new.board, new.fak, new.subscriber, new.phone, new.prev, new.mode, new.assignee_id, new.file_id, new.sheet)
       is distinct from (old.batch_id, old.ord, old.sheet_row, old.code, old.area, old.board, old.fak, old.subscriber, old.phone, old.prev, old.mode, old.assignee_id, old.file_id, old.sheet) then
      raise exception 'not_allowed';
    end if;
    new.source := 'app';
  end if;
  if (new.reading, new.state, new.note) is distinct from (old.reading, old.state, old.note) then
    new.entered_by := me;
    new.entered_at := now();
    if adm and new.source is null then new.source := coalesce(old.mode, 'paper'); end if;
  end if;
  new.updated_at := now();
  return new;
end $$;

-- ===================== 20261030000032_company_sms.sql =====================

-- =====================================================================
--  نظام مخيم 2: SMS من اشتراك الشركة (هوت SMS / ورلد لينكس)
-- =====================================================================
-- The office's SMS go out from the company's subscription, sent by the database itself (the «http»
-- add-on), so the login never reaches a phone or the code. The manager types the login once in
-- Settings; it is kept in m2_ops (out of the app's reach) and is never read back.

do $$
begin
  -- Supabase has it; a bare test database may not (sending then answers «network»).
  if exists (select 1 from pg_available_extensions where name = 'http') then
    create schema if not exists extensions;
    create extension if not exists http with schema extensions;
  end if;
end $$;
create schema if not exists m2_ops;
revoke all on schema m2_ops from public;

create table if not exists m2_ops.sms_config (
  id integer primary key default 1 check (id = 1),
  user_name text,
  user_pass text,
  sender text not null default 'AF Camp2',
  updated_at timestamptz not null default now()
);

-- One call to the provider; returns what it answered (1001 = sent, 1000 = no balance, 2000 = login…).
create or replace function m2_ops.hotsms(p_page text, p_params jsonb) returns text
language plpgsql security definer set search_path = public, extensions as $$
declare
  cfg m2_ops.sms_config;
  res record;
begin
  select * into cfg from m2_ops.sms_config where id = 1;
  if cfg.user_name is null or cfg.user_pass is null then return 'no_login'; end if;
  perform extensions.http_set_curlopt('CURLOPT_TIMEOUT_MS', '6000');
  select status, content into res
    from extensions.http_get('https://hotsms.ps/' || p_page,
      p_params || jsonb_build_object('user_name', cfg.user_name, 'user_pass', cfg.user_pass));
  if res.status is distinct from 200 then return 'http_' || coalesce(res.status::text, '0'); end if;
  return btrim(coalesce(res.content, ''), E' \r\n\t');
exception when others then
  return 'network';
end $$;
revoke all on function m2_ops.hotsms(text, jsonb) from public;

-- The manager saves the login (an empty password keeps the old one). Nothing ever reads it back.
create or replace function public.sms_set_login(p_user text, p_pass text, p_sender text) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  insert into m2_ops.sms_config (id, user_name, user_pass, sender)
  values (1, nullif(btrim(p_user), ''), nullif(p_pass, ''), coalesce(nullif(btrim(p_sender), ''), 'AF Camp2'))
  on conflict (id) do update set
    user_name = coalesce(nullif(btrim(p_user), ''), m2_ops.sms_config.user_name),
    user_pass = coalesce(nullif(p_pass, ''), m2_ops.sms_config.user_pass),
    sender = coalesce(nullif(btrim(p_sender), ''), m2_ops.sms_config.sender),
    updated_at = now();
end $$;

-- Is it set up (and with which sender name)? The balance comes with it when asked.
create or replace function public.sms_info(p_balance boolean default false) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  cfg m2_ops.sms_config;
begin
  if not (public.is_manager() or public.has_page('tasks')) then raise exception 'not_allowed' using errcode = '42501'; end if;
  select * into cfg from m2_ops.sms_config where id = 1;
  return jsonb_build_object(
    'ready', cfg.user_name is not null and cfg.user_pass is not null,
    'user', case when public.is_manager() then cfg.user_name end,
    'sender', coalesce(cfg.sender, 'AF Camp2'),
    'balance', case when p_balance and cfg.user_name is not null then m2_ops.hotsms('getbalance.php', '{}'::jsonb) end
  );
end $$;

-- Sends one text to a few numbers (05xxxxxxxx) from the company's subscription; each is logged.
-- A task's order marks the task sent only when the provider took it.
create or replace function public.sms_send(p_phones text[], p_text text, p_task uuid default null) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  cfg m2_ops.sms_config;
  ph text;
  code text;
  ok boolean;
  sent integer := 0;
  failed jsonb := '[]'::jsonb;
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if coalesce(btrim(p_text), '') = '' then raise exception 'empty_text'; end if;
  if length(p_text) > 335 then raise exception 'too_long'; end if;
  if coalesce(array_length(p_phones, 1), 0) = 0 or array_length(p_phones, 1) > 5 then raise exception 'bad_count'; end if;
  select * into cfg from m2_ops.sms_config where id = 1;
  foreach ph in array p_phones loop
    if ph !~ '^05[0-9]{8}$' then
      failed := failed || jsonb_build_object('phone', ph, 'code', '5000');
      continue;
    end if;
    code := m2_ops.hotsms('sendbulksms.php', jsonb_build_object(
      'sender', coalesce(cfg.sender, 'AF Camp2'), 'mobile', '972' || substr(ph, 2), 'type', '2', 'text', p_text));
    ok := code like '1001%';
    insert into public.outgoing_messages (task_id, channel, to_phone, body, status, provider, provider_ref, error, sent_at)
    values (p_task, 'sms', ph, p_text, case when ok then 'sent' else 'failed' end::public.message_status,
            'hotsms', code, case when ok then null else code end, case when ok then now() end);
    if ok then sent := sent + 1; else failed := failed || jsonb_build_object('phone', ph, 'code', code); end if;
  end loop;
  return jsonb_build_object('sent', sent, 'failed', failed);
end $$;

-- Logging a send marks the task sent, unless the provider refused it.
create or replace function public.outgoing_message_logged() returns trigger
language plpgsql security definer set search_path = public as $$
begin
  new.created_by := coalesce(public.current_employee_id(), new.created_by);
  if new.task_id is not null and new.status is distinct from 'failed' then
    insert into public.task_events (task_id, event, actor_id, meta)
      values (new.task_id, case new.channel when 'sms' then 'sent_sms' else 'sent_whatsapp' end, new.created_by,
              jsonb_build_object('to', new.to_phone, 'via', coalesce(new.provider, 'phone')));
    update public.tasks set status = 'sent' where id = new.task_id and status = 'new';
  end if;
  return new;
end $$;

revoke execute on function public.sms_set_login(text, text, text), public.sms_info(boolean), public.sms_send(text[], text, uuid) from anon, public;
grant execute on function public.sms_set_login(text, text, text), public.sms_info(boolean), public.sms_send(text[], text, uuid) to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000033_activity_archive.sql =====================

-- Reuse immutable audit references, without exposing private row snapshots to the UI.
alter table public.audit_log drop constraint if exists audit_log_action_check;
alter table public.audit_log add constraint audit_log_action_check check (action in ('insert','update','delete'));
create index if not exists audit_log_recent on public.audit_log (id desc);
do $$ declare t text; begin
 foreach t in array array['seal_rolls','seal_batches','tasks','attendance_punches','leaves','site_reports','distribution_sheets','reading_batches'] loop
  execute format('drop trigger if exists %I on public.%I',t||'_audit_insert',t);
  execute format('create trigger %I after insert on public.%I for each row execute function public.audit_row()',t||'_audit_insert',t);
 end loop;
end $$;

drop trigger if exists reading_rows_activity_audit on public.reading_rows;
create trigger reading_rows_activity_audit after update of reading on public.reading_rows for each row when (old.reading is distinct from new.reading) execute function public.audit_row();

create or replace function public.activity_label(p_table text,p_action text,p_old jsonb,p_new jsonb)
returns text language plpgsql immutable set search_path=public as $$
declare r jsonb:=coalesce(p_new,p_old); verb text:=case p_action when 'insert' then 'أضاف' when 'delete' then 'حذف' else 'عدّل' end;
begin return case p_table
 when 'seal_rolls' then verb||' رول أختام '||coalesce(r->>'from_no','')||'–'||coalesce(r->>'to_no','')
 when 'seal_batches' then verb||' دفعة أختام #'||coalesce(r->>'batch_no','')
 when 'seals' then case when p_action='delete' then 'حذف' when r->>'status'='used' then 'سجّل استخدام' when r->>'status'='issued' then case when p_old->>'status'='used' then 'ألغى تسجيل استخدام' else 'صرف' end when r->>'status'='in_stock' then 'أعاد للمخزن' else 'عدّل حالة' end||' الختم '||coalesce(r->>'seal_no','')||case when nullif(r->>'details','') is not null then ' · '||left(r->>'details',160) else '' end
 when 'tasks' then case when r->>'status'='done' then 'أنهى' when r->>'status'='cancelled' then 'ألغى' when r->>'status'='in_progress' then 'بدأ' else verb end||' مهمة #'||coalesce(r->>'number','')||case when nullif(r->>'subscriber_name','') is not null then ' · '||left(r->>'subscriber_name',100) else '' end
 when 'attendance_punches' then case when p_action='delete' then 'حذف تسجيل حضور' when r->>'kind'='in' then 'سجّل حضور' else 'سجّل انصراف' end
 when 'leaves' then verb||' إجازة'
 when 'site_reports' then case when r->>'status'='approved' then 'اعتمد' when r->>'status'='submitted' then 'أرسل' else verb end||' تقرير التوليد · '||coalesce(r->>'report_date','')
 when 'distribution_sheets' then case when r->>'status'='approved' then 'اعتمد' when r->>'status'='submitted' then 'أرسل' else verb end||' كشف التوزيع · '||coalesce(r->>'sheet_date','')
 when 'reading_batches' then verb||' كشف قراءات · '||left(coalesce(r->>'title',''),100)
 when 'reading_rows' then 'سجّل قراءة · '||left(coalesce(r->>'subscriber',''),100)
 when 'employees' then verb||' بيانات موظف'
 when 'app_settings' then 'حدّث إعدادات المكتب'
 when 'generators' then verb||' مولد'
 when 'zones' then verb||' منطقة توزيع'
 when 'task_types' then verb||' نوع مهمة'
 when 'work_schedules' then 'عدّل مواعيد الدوام'
 else verb||' سجل' end;
end $$;
revoke all on function public.activity_label(text,text,jsonb,jsonb) from public,anon,authenticated;

create or replace function public.recent_activity(p_limit integer default 80)
returns table(id bigint,at timestamptz,kind text,who text,text text,tone text,route text)
language plpgsql stable security definer set search_path=public as $$
begin
 if not public.is_manager() then raise exception 'not_allowed' using errcode='42501'; end if;
 return query select a.id,a.at,
 case when a.table_name in ('seal_rolls','seal_batches','seals') then 'seal' when a.table_name='tasks' then 'task' when a.table_name in ('attendance_punches','leaves') then 'attendance' when a.table_name='site_reports' then 'report' when a.table_name='distribution_sheets' then 'sheet' when a.table_name in ('reading_batches','reading_rows') then 'reading' else 'settings' end,
 coalesce(e.full_name,'النظام'),public.activity_label(a.table_name,a.action,a.old_row,a.new_row)||case when target.id is not null and target.id is distinct from e.id then ' · '||target.full_name else '' end,
 case when a.action='delete' then 'danger' when a.new_row->>'status' in ('done','approved','used') then 'ok' else null end,
 case when a.table_name in ('seal_rolls','seal_batches','seals') then '/seals/log' when a.table_name='tasks' then '/tasks?view=archive' when a.table_name in ('attendance_punches','leaves') then '/attendance' when a.table_name='site_reports' then '/generation' when a.table_name='distribution_sheets' then '/distribution' when a.table_name in ('reading_batches','reading_rows') then '/readings' else '/settings' end
 from public.audit_log a left join public.employees e on e.id=coalesce(a.actor_id,nullif(coalesce(a.new_row,a.old_row)->>'employee_id','')::uuid,case when a.table_name='tasks' then nullif(coalesce(a.new_row,a.old_row)->>'assignee_id','')::uuid end)
 left join public.employees target on target.id=coalesce(nullif(coalesce(a.new_row,a.old_row)->>'employee_id','')::uuid,nullif(coalesce(a.new_row,a.old_row)->>'assignee_id','')::uuid,nullif(coalesce(a.new_row,a.old_row)->>'technician_id','')::uuid)
 where a.table_name in ('seal_rolls','seal_batches','seals','tasks','attendance_punches','leaves','site_reports','distribution_sheets','reading_batches','reading_rows','employees','app_settings','generators','zones','task_types','work_schedules')
 -- Issuing a batch is one notification, rather than one for each seal.
 and not (a.table_name='seals' and a.action='update' and a.old_row->>'status'='in_stock' and a.new_row->>'status'='issued' and exists (select 1 from public.audit_log batch where batch.table_name='seal_batches' and batch.action='insert' and batch.record_id=a.new_row->>'batch_id' and batch.at=a.at))
 and not (a.table_name in ('site_reports','distribution_sheets') and a.action='update' and a.old_row->>'status'=a.new_row->>'status')
 order by a.id desc limit greatest(1,least(coalesce(p_limit,80),200));
end $$;

create or replace function public.seal_activity(p_table text default null,p_record text default null,p_actor uuid default null,p_before bigint default null)
returns table(id bigint,at timestamptz,who text,text text,record_id text,table_name text)
language plpgsql stable security definer set search_path=public as $$
begin
 if not public.has_seals() then raise exception 'not_allowed' using errcode='42501'; end if;
 if p_table is not null and p_table not in ('seal_rolls','seal_batches','seals') then raise exception 'not_allowed' using errcode='42501'; end if;
 return query select a.id,a.at,coalesce(e.full_name,'النظام'),public.activity_label(a.table_name,a.action,a.old_row,a.new_row),a.record_id,a.table_name
 from public.audit_log a left join public.employees e on e.id=a.actor_id
 where a.table_name in ('seal_rolls','seal_batches','seals') and (p_actor is null or a.actor_id=p_actor) and (p_before is null or a.id<p_before)
 and (p_record is null or (a.table_name=p_table and a.record_id=p_record)
 or (p_table='seal_rolls' and (a.old_row->>'roll_id'=p_record or a.new_row->>'roll_id'=p_record))
 or (p_table='seal_batches' and (a.old_row->>'batch_id'=p_record or a.new_row->>'batch_id'=p_record)))
 order by a.id desc limit 100;
end $$;
revoke all on function public.recent_activity(integer),public.seal_activity(text,text,uuid,bigint) from public,anon;
grant execute on function public.recent_activity(integer),public.seal_activity(text,text,uuid,bigint) to authenticated;
do $$ begin
 if exists(select 1 from pg_publication where pubname='supabase_realtime') and not exists(select 1 from pg_publication_tables where pubname='supabase_realtime' and schemaname='public' and tablename='audit_log') then
 alter publication supabase_realtime add table public.audit_log;
 end if;
end $$;
notify pgrst, 'reload schema';

-- ===================== 20261030000034_task_cancel_confirmation.sql =====================

-- =====================================================================
-- مخيم 2: إلغاء المهمة بعد التأكيد فقط، بدون إلزام الموظف بكتابة سبب
-- =====================================================================
-- Keep permissions, closed-task protections, server timestamps and cancellation history.
-- Existing optional reasons (including those submitted by older clients) stay supported.

create or replace function public.tasks_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  acting uuid := nullif(current_setting('m2.acting_employee', true), '')::uuid;
  me uuid := coalesce(acting, public.current_employee_id());
  mgr boolean := acting is null and (public.is_manager() or public.has_page('tasks'));
  t timestamptz;
begin
  if tg_op = 'INSERT' then
    new.created_by := coalesce(me, new.created_by);
    new.status := 'new';
    new.sent_at := null; new.seen_at := null; new.started_at := null;
    new.completed_at := null; new.cancelled_at := null;
    return new;
  end if;

  if not mgr then
    if me is null or old.assignee_id is distinct from me then
      raise exception 'This task is not assigned to you';
    end if;
    if (new.task_type_id, new.assignee_id, new.details, new.subscriber_name, new.subscriber_phone,
        new.zone_id, new.location_text, new.priority, new.expected_minutes, new.created_by, new.cancel_reason, new.link_token)
       is distinct from
       (old.task_type_id, old.assignee_id, old.details, old.subscriber_name, old.subscriber_phone,
        old.zone_id, old.location_text, old.priority, old.expected_minutes, old.created_by, old.cancel_reason, old.link_token) then
      raise exception 'A technician can only start, finish and add notes to a task';
    end if;
    if new.status is distinct from old.status and not (
         (old.status in ('new', 'sent') and new.status = 'seen')
      or (old.status in ('new', 'sent', 'seen') and new.status = 'in_progress')
      or (old.status = 'in_progress' and new.status = 'done')) then
      raise exception 'Invalid task step';
    end if;
  else
    if new.assignee_id is distinct from old.assignee_id then
      if old.status not in ('new', 'sent', 'seen') then
        raise exception 'A started or closed task cannot be reassigned';
      end if;
      new.status := 'new';
      new.sent_at := null; new.seen_at := null;
      insert into public.task_events (task_id, event, actor_id, meta)
        values (new.id, 'reassigned', me, jsonb_build_object('from', old.assignee_id, 'to', new.assignee_id));
    elsif new.status is distinct from old.status and not (
         (old.status = 'new' and new.status = 'sent')
      or (old.status in ('new', 'sent', 'seen', 'in_progress') and new.status = 'cancelled')
      -- A technician without a smartphone: the office marks the task done for him.
      or (old.status in ('new', 'sent', 'seen', 'in_progress') and new.status = 'done' and new.assignee_id is not null)) then
      raise exception 'The manager can send or cancel a task; the technician starts and finishes it';
    end if;
  end if;

  -- Server-owned times: copied from the old row unless this update is the step that sets them.
  new.sent_at := coalesce(new.sent_at, old.sent_at);
  if new.assignee_id is not distinct from old.assignee_id then
    new.sent_at := old.sent_at; new.seen_at := old.seen_at;
  end if;
  new.started_at := old.started_at; new.completed_at := old.completed_at; new.cancelled_at := old.cancelled_at;

  if new.status is distinct from old.status then
    t := public.event_time(new.recorded_offline, new.device_time, coalesce(old.started_at, old.sent_at, old.created_at));
    case new.status
      when 'sent' then
        new.sent_at := now();
      when 'seen' then
        new.seen_at := t;
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'seen', me, t, new.recorded_offline);
      when 'in_progress' then
        new.seen_at := coalesce(new.seen_at, t);
        new.started_at := t;
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'started', me, t, new.recorded_offline);
      when 'done' then
        new.started_at := coalesce(new.started_at, least(t, coalesce(old.seen_at, old.sent_at, t)));
        new.completed_at := greatest(t, new.started_at);
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'completed', me, new.completed_at, new.recorded_offline);
      when 'cancelled' then
        new.cancel_reason := nullif(btrim(coalesce(new.cancel_reason, '')), '');
        new.cancelled_at := now();
        insert into public.task_events (task_id, event, actor_id) values (new.id, 'cancelled', me);
      else
        null;
    end case;
  end if;
  return new;
end $$;


notify pgrst, 'reload schema';

-- ===================== 20261030000035_hourly_loads.sql =====================

-- =====================================================================
--  نظام مخيم 2: الأحمال حسب الساعة (جدول 9 · 12 · 3 · 6 · 9 · 12)
-- =====================================================================
-- Six bands of the day (7–9, 9–12, 12–3, 3–6, 6–9, 9–12 at night), as on the paper sheets.
--  · Distribution: per zone, three readings in every band  -> zone_day_entries.band_loads  [[a,b,c] x 6]
--  · Generation: per generator, one reading in every band  -> generator_day_logs.band_loads [a x 6]
-- An empty cell is null (a dash on the sheet). The old L1/L2/L3 columns stay for the days already sent.

alter table public.zone_day_entries add column if not exists band_loads jsonb;
alter table public.generator_day_logs add column if not exists band_loads jsonb;

alter table public.zone_day_entries drop constraint if exists zone_day_entries_band_loads_shape;
alter table public.zone_day_entries add constraint zone_day_entries_band_loads_shape
  check (band_loads is null or (jsonb_typeof(band_loads) = 'array' and jsonb_array_length(band_loads) = 6));
alter table public.generator_day_logs drop constraint if exists generator_day_logs_band_loads_shape;
alter table public.generator_day_logs add constraint generator_day_logs_band_loads_shape
  check (band_loads is null or (jsonb_typeof(band_loads) = 'array' and jsonb_array_length(band_loads) = 6));

notify pgrst, 'reload schema';

-- ===================== 20261030000036_pages_fill_forms.sql =====================

-- =====================================================================
--  نظام مخيم 2: اللي انفتحت له صفحة «التوليد» أو «التوزيع» يعبّي ويرسل
-- =====================================================================
-- Until now a page opened for someone (Settings › Permissions) was for looking only. Now whoever is given
-- «التوليد» fills and sends the generation report, and whoever is given «التوزيع» fills and sends the
-- distribution sheet, exactly as the site staff do (draft or reopened day only; the manager approves).

-- Only what was given to the person: managers do not count here (they have their own rules).
create or replace function public.has_own_page(p_page text) returns boolean
language sql stable security definer set search_path = public as $$
  select exists (
    select 1 from public.employees e
     where e.id = public.current_employee_id() and e.is_active and p_page = any (e.pages)
  )
$$;

create or replace function public.can_fill_generation() returns boolean
language sql stable security definer set search_path = public as $$
  select public.has_role('generation_operator', 'distribution_supervisor') or public.has_own_page('generation')
$$;

create or replace function public.can_fill_distribution() returns boolean
language sql stable security definer set search_path = public as $$
  select public.has_role('generation_operator', 'distribution_supervisor') or public.has_own_page('distribution')
$$;

-- «Site staff» (who may also add a generator from the report) now includes them.
create or replace function public.is_site_staff() returns boolean
language sql stable security definer set search_path = public as $$
  select public.can_fill_generation() or public.can_fill_distribution()
$$;

create or replace function public.site_report_editable(p_report_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_manager() or (
    public.can_fill_generation()
    and exists (select 1 from public.site_reports where id = p_report_id and status in ('draft', 'returned'))
  )
$$;

create or replace function public.distribution_sheet_editable(p_sheet_id uuid) returns boolean
language sql stable security definer set search_path = public as $$
  select public.is_manager() or (
    public.can_fill_distribution()
    and exists (select 1 from public.distribution_sheets where id = p_sheet_id and status in ('draft', 'returned'))
  )
$$;

-- Same steps as before; «site» is whoever fills this kind of sheet (by role or by the page given).
create or replace function public.sheet_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  r public.user_role := public.current_user_role();
  me uuid := public.current_employee_id();
  site boolean := r not in ('admin', 'manager') and case tg_table_name
    when 'site_reports' then public.can_fill_generation()
    else public.can_fill_distribution() end;
begin
  if tg_op = 'INSERT' then
    if new.status not in ('draft', 'submitted') then
      raise exception 'A new sheet starts as draft or submitted';
    end if;
    new.created_by := coalesce(me, new.created_by);
    new.submitted_by := null; new.submitted_at := null;
    new.approved_by := null; new.approved_at := null;
    if new.status = 'submitted' then
      new.submitted_by := me;
      new.submitted_at := public.event_time(new.recorded_offline, new.device_time, null);
    end if;
    return new;
  end if;

  if site and old.status in ('submitted', 'approved') then
    raise exception 'This sheet was sent and can no longer be edited by site staff';
  end if;

  if new.status is distinct from old.status then
    if site and not (old.status in ('draft', 'returned') and new.status = 'submitted') then
      raise exception 'Site staff can only send a draft or returned sheet';
    end if;
    if r = 'manager' and not (
         (old.status = 'submitted' and new.status in ('approved', 'returned'))
      or (old.status = 'approved' and new.status = 'returned')
      or (old.status in ('draft', 'returned') and new.status = 'submitted')) then
      raise exception 'The manager can fill and close a day, approve a closed day or reopen it';
    end if;
    if not site and r is distinct from 'manager' and r is distinct from 'admin' then
      raise exception 'Not allowed';
    end if;
    if new.status = 'submitted' then
      new.submitted_by := me;
      new.submitted_at := public.event_time(new.recorded_offline, new.device_time, null);
      new.returned_reason := null;
    elsif new.status = 'approved' then
      new.approved_by := me;
      new.approved_at := now();
    elsif new.status = 'returned' then
      if length(btrim(coalesce(new.returned_reason, ''))) = 0 then
        raise exception 'Reopening a day needs a reason';
      end if;
      new.approved_by := null; new.approved_at := null;
    end if;
  else
    new.submitted_by := old.submitted_by; new.submitted_at := old.submitted_at;
    new.approved_by := old.approved_by; new.approved_at := old.approved_at;
  end if;
  new.created_by := old.created_by;
  return new;
end $$;

-- Reading, starting and updating each form.
do $$
declare t text;
begin
  execute 'alter policy site_reports_read on public.site_reports using (public.can_fill_generation() or public.has_page(''generation''))';
  execute 'alter policy site_reports_insert on public.site_reports with check (public.is_manager() or public.can_fill_generation())';
  execute 'alter policy site_reports_update on public.site_reports using (public.is_manager() or public.can_fill_generation()) with check (public.is_manager() or public.can_fill_generation())';
  execute 'alter policy distribution_sheets_read on public.distribution_sheets using (public.can_fill_distribution() or public.has_page(''distribution''))';
  execute 'alter policy distribution_sheets_insert on public.distribution_sheets with check (public.is_manager() or public.can_fill_distribution())';
  execute 'alter policy distribution_sheets_update on public.distribution_sheets using (public.is_manager() or public.can_fill_distribution()) with check (public.is_manager() or public.can_fill_distribution())';
  foreach t in array array['site_report_fuel', 'generator_day_logs', 'generator_runs', 'maintenance_logs'] loop
    execute format('alter policy %I on public.%I using (public.can_fill_generation() or public.has_page(''generation''))', t || '_read', t);
  end loop;
  foreach t in array array['zone_day_entries', 'zone_runs'] loop
    execute format('alter policy %I on public.%I using (public.can_fill_distribution() or public.has_page(''distribution''))', t || '_read', t);
  end loop;
end $$;

revoke execute on function public.has_own_page(text), public.can_fill_generation(), public.can_fill_distribution(), public.is_site_staff() from anon, public;
grant execute on function public.has_own_page(text), public.can_fill_generation(), public.can_fill_distribution(), public.is_site_staff() to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000037_client_issues.sql =====================

-- Minimal, bounded diagnostics. No free-form error messages, URL queries or form data.
create table if not exists public.client_issues (
 id uuid primary key, employee_id uuid not null references public.employees(id), at timestamptz not null default now(),
 kind text not null check(kind in ('render','error','promise')), code text not null check(code in ('Error','TypeError','RangeError','ReferenceError','SyntaxError','URIError','EvalError','AggregateError')),
 route text not null check(length(route)<=120 and route ~ '^/[a-z0-9/\[\]:-]*$'),
 location text not null check(length(location)<=240), build text not null check(length(build)<=40)
);
alter table public.client_issues enable row level security;
create index if not exists client_issues_at on public.client_issues(at);
create or replace function public.report_client_issue(p_id uuid,p_kind text,p_code text,p_route text,p_location text,p_build text) returns void
language plpgsql security definer set search_path=public as $$
declare who uuid:=public.current_employee_id();begin
 if who is null or not exists(select 1 from public.employees where id=who and is_active and deleted_at is null) then raise exception 'not_allowed' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtext('m2-client-issues'));
 delete from public.client_issues where at<now()-interval '30 days';
 if exists(select 1 from public.client_issues where id=p_id) then return;end if;
 if (select count(*) from public.client_issues where employee_id=who and at>now()-interval '1 hour')>=10 then raise exception 'rate_limit';end if;
 if p_location !~ '^(/assets/[A-Za-z0-9_-]+\.js:[0-9]+:[0-9]+ ?){0,3}$' or p_build !~ '^[A-Za-z0-9:.+_-]{0,40}$' then raise exception 'invalid_diagnostic';end if;
 delete from public.client_issues where id in (select id from public.client_issues order by at desc offset 9999);
 insert into public.client_issues(id,employee_id,kind,code,route,location,build) values(p_id,who,p_kind,p_code,p_route,p_location,p_build);
end $$;
create or replace function public.recent_client_issues() returns table(id uuid,at timestamptz,kind text,code text,route text,location text,build text,who text)
language plpgsql stable security definer set search_path=public as $$begin
 if not public.is_manager() then raise exception 'not_allowed' using errcode='42501';end if;
 return query select i.id,i.at,i.kind,i.code,i.route,i.location,i.build,e.full_name from public.client_issues i join public.employees e on e.id=i.employee_id where i.at>now()-interval '30 days' order by i.at desc limit 200;
end $$;
revoke all on public.client_issues from anon,authenticated;
revoke execute on function public.report_client_issue(uuid,text,text,text,text,text),public.recent_client_issues() from public,anon;
grant execute on function public.report_client_issue(uuid,text,text,text,text,text),public.recent_client_issues() to authenticated;
notify pgrst,'reload schema';

-- ===================== 20261030000038_second_audit.sql =====================

-- Second audit batch: restricted staff directory, opt-in cold archives, and an Auth hook.
-- No historical data is deleted by installation. Archives require a separate manager action.

alter policy employees_read on public.employees
  using (public.is_manager() or id = public.current_employee_id());

create or replace function public.employee_directory() returns setof public.employees
language plpgsql stable security definer set search_path=public as $$
declare me uuid:=public.current_employee_id(); office boolean; dispatcher boolean;
begin
 if me is null then raise exception 'not_allowed' using errcode='42501'; end if;
 office:=public.has_role('generation_operator','distribution_supervisor') or public.has_page('tasks') or public.has_page('attendance') or public.has_page('reports') or public.has_page('generation') or public.has_page('distribution') or public.has_page('readings-admin');
 dispatcher:=public.has_page('tasks');
 return query select (case when public.is_manager() or e.id=me then e else jsonb_populate_record(null::public.employees,jsonb_build_object(
  'id',e.id,'full_name',e.full_name,'role',e.role,'is_active',e.is_active,'deleted_at',e.deleted_at,'job_title',e.job_title,
  'phone',case when dispatcher and e.role='technician' and e.is_active and e.deleted_at is null then e.phone else null end,
  'tracks_attendance',case when public.has_page('attendance') or public.has_page('reports') then e.tracks_attendance else false end,
  'schedule_id',case when public.has_page('attendance') or public.has_page('reports') then e.schedule_id else null end,
  'can_seals',false,'seals_sheet',case when public.has_seals() then e.seals_sheet else null end,'pages',case when public.has_page('readings-admin') and e.role='technician' and 'readings'=any(coalesce(e.pages,'{}')) then '["readings"]'::jsonb else '[]'::jsonb end,'auth_user_id',null,'wa_code',e.wa_code)) end).*
 from public.employees e where public.is_manager() or e.id=me or ((
  (office and (e.role in ('admin','manager','generation_operator','distribution_supervisor','technician') or public.has_page('attendance') or public.has_page('reports')))
  or (public.has_seals() and e.role='technician')
  or ((office or public.has_seals()) and e.job_title in ('مدير الموقع','مدير المكتب')))) order by e.full_name,e.id;
end $$;
revoke all on function public.employee_directory() from public,anon;
grant execute on function public.employee_directory() to authenticated;

-- Hook must also be enabled in Supabase Auth settings. It does not revoke existing sessions.
create table if not exists m2_ops.login_attempts (
 user_id uuid primary key references auth.users(id) on delete cascade,
 started_at timestamptz not null, failures integer not null default 0,
 blocked_until timestamptz
);
revoke all on m2_ops.login_attempts from public,anon,authenticated;
create or replace function public.password_verification_attempt_hook(event jsonb) returns jsonb
language plpgsql security definer set search_path=public,m2_ops as $$
declare who uuid; valid boolean; a m2_ops.login_attempts%rowtype; moment timestamptz:=clock_timestamp();
begin
 who:=(event->>'user_id')::uuid;valid:=(event->>'valid')::boolean;
 if who is null or valid is null or not exists(select 1 from auth.users where id=who) then return jsonb_build_object('decision','reject','message','تعذّر الدخول','should_logout_user',false);end if;
 perform pg_advisory_xact_lock(hashtextextended('m2-login:'||who::text,0));
 delete from m2_ops.login_attempts where started_at<moment-interval '1 day' and coalesce(blocked_until,moment-interval '1 second')<moment;
 insert into m2_ops.login_attempts(user_id,started_at) values(who,moment) on conflict do nothing;
 select * into a from m2_ops.login_attempts where user_id=who for update;
 if a.blocked_until>moment then return jsonb_build_object('decision','reject','message','محاولات كثيرة. استنى ربع ساعة وحاول من جديد.','should_logout_user',false);end if;
 if valid then delete from m2_ops.login_attempts where user_id=who;return jsonb_build_object('decision','continue');end if;
 if a.started_at<=moment-interval '15 minutes' then a.failures:=0;a.started_at:=moment;end if;
 a.failures:=a.failures+1;
 update m2_ops.login_attempts set started_at=a.started_at,failures=a.failures,blocked_until=case when a.failures>=5 then moment+interval '15 minutes' else null end where user_id=who;
 if a.failures>=5 then return jsonb_build_object('decision','reject','message','محاولات كثيرة. استنى ربع ساعة وحاول من جديد.','should_logout_user',false);end if;
 return jsonb_build_object('decision','continue');
end $$;
revoke all on function public.password_verification_attempt_hook(jsonb) from public,anon,authenticated;
do $$ begin if exists(select 1 from pg_roles where rolname='supabase_auth_admin') then
 grant usage on schema public to supabase_auth_admin;
 grant execute on function public.password_verification_attempt_hook(jsonb) to supabase_auth_admin;
end if;end $$;

-- Archive receipts tie cleanup to exactly the records offered for download, for one manager/day.
create table if not exists m2_ops.archive_receipts (
 id uuid primary key default gen_random_uuid(), employee_id uuid not null references public.employees(id),
 kind text not null check(kind in ('audit','reading')),batch_id uuid,ids bigint[],fingerprint text not null,
 created_at timestamptz not null default now(),consumed_at timestamptz
);
revoke all on m2_ops.archive_receipts from public,anon,authenticated;
alter table public.reading_files add column if not exists archived_at timestamptz;
alter table public.reading_files add column if not exists archived_digest text;
alter table public.reading_batches add column if not exists archived_at timestamptz;
alter table public.reading_batches add column if not exists archived_digest text;
create index if not exists audit_log_retention on public.audit_log(at,id);

create or replace function public.storage_overview() returns jsonb
language plpgsql stable security definer set search_path=public as $$
begin
 if not public.is_manager() then raise exception 'not_allowed' using errcode='42501';end if;
 return jsonb_build_object('audit_count',(select count(*) from public.audit_log),
 'old_audit_count',(select count(*) from public.audit_log where at<now()-interval '1 year'),
 'audit_bytes',(select pg_total_relation_size('public.audit_log')),
 'reading_bytes',(select coalesce(sum(octet_length(source_b64)),0) from public.reading_files),
 'batches',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'title',b.title,'date',coalesce(b.period_to,b.created_at::date),'archived',b.archived_at is not null,'files',(select count(*) from public.reading_files f where f.batch_id=b.id),'bytes',coalesce(octet_length(b.source_b64),0)+(select coalesce(sum(octet_length(f.source_b64)),0) from public.reading_files f where f.batch_id=b.id)) order by coalesce(b.period_to,b.created_at::date)), '[]'::jsonb) from public.reading_batches b where b.status='approved' and coalesce(b.period_to,b.created_at::date)<current_date-365));
end $$;

create or replace function public.prepare_cold_archive(p_kind text,p_batch uuid default null) returns jsonb
language plpgsql security definer set search_path=public,m2_ops as $$
declare receipt uuid; who uuid:=public.current_employee_id(); ids bigint[]; data jsonb; fingerprint text; b public.reading_batches%rowtype;
begin
 if not public.is_manager() then raise exception 'not_allowed' using errcode='42501';end if;
 delete from m2_ops.archive_receipts where created_at<now()-interval '1 day';
 if (select count(*) from m2_ops.archive_receipts where employee_id=who and consumed_at is null)>=20 then raise exception 'archive_limit';end if;
 if p_kind='audit' then
  select array_agg(x.id order by x.id),md5(string_agg(x.id::text||':'||md5(to_jsonb(x)::text),',' order by x.id)),
    jsonb_agg(jsonb_build_object('id',x.id,'table_name',x.table_name,'record_id',x.record_id,'action',x.action,'actor_id',x.actor_id,'at',x.at,'text',public.activity_label(x.table_name,x.action,x.old_row,x.new_row),'old_row',x.old_row-array['pin','password','token','link_token','source_b64','auth_user_id','code','data'],'new_row',x.new_row-array['pin','password','token','link_token','source_b64','auth_user_id','code','data']) order by x.id)
   into ids,fingerprint,data from (select * from public.audit_log where at<now()-interval '1 year' order by id limit 5000) x;
  if ids is null then raise exception 'nothing_to_archive';end if;
 elsif p_kind='reading' then
  select * into b from public.reading_batches where id=p_batch for update;
  if b.id is null or b.status<>'approved' or coalesce(b.period_to,b.created_at::date)>=current_date-365 or b.archived_at is not null then raise exception 'archive_not_allowed';end if;
  perform 1 from public.reading_files where batch_id=p_batch for update;
  perform 1 from public.reading_rows where batch_id=p_batch for share;
  data:=jsonb_build_object('batch',to_jsonb(b),'files',(select coalesce(jsonb_agg(to_jsonb(f) order by id),'[]'::jsonb) from public.reading_files f where batch_id=p_batch),'rows',(select coalesce(jsonb_agg(to_jsonb(r) order by ord),'[]'::jsonb) from public.reading_rows r where batch_id=p_batch));
  fingerprint:=md5(data::text);
 else raise exception 'archive_not_allowed';end if;
 insert into m2_ops.archive_receipts(employee_id,kind,batch_id,ids,fingerprint) values(who,p_kind,p_batch,ids,fingerprint) returning id into receipt;
 return jsonb_build_object('app','mukhayyam2','kind',p_kind,'version',1,'receipt',receipt,'data',data);
end $$;

create or replace function public.finish_cold_archive(p_receipt uuid) returns integer
language plpgsql security definer set search_path=public,m2_ops as $$
declare r m2_ops.archive_receipts%rowtype; actual text; b public.reading_batches%rowtype; data jsonb; affected integer;
begin
 if not public.is_manager() then raise exception 'not_allowed' using errcode='42501';end if;
 select * into r from m2_ops.archive_receipts where id=p_receipt and employee_id=public.current_employee_id() and consumed_at is null and created_at>now()-interval '1 day' for update;
 if r.id is null then raise exception 'archive_expired';end if;
 if r.kind='audit' then
  select md5(string_agg(x.id::text||':'||md5(to_jsonb(x)::text),',' order by x.id)) into actual from public.audit_log x where x.id=any(r.ids) and x.at<now()-interval '1 year';
  if actual is distinct from r.fingerprint then raise exception 'archive_changed';end if;
  delete from public.audit_log where id=any(r.ids);get diagnostics affected=row_count;
 else
  select * into b from public.reading_batches where id=r.batch_id for update;
  if b.status<>'approved' or coalesce(b.period_to,b.created_at::date)>=current_date-365 or b.archived_at is not null then raise exception 'archive_changed';end if;
  perform 1 from public.reading_files where batch_id=r.batch_id for update;
  perform 1 from public.reading_rows where batch_id=r.batch_id for share;
  data:=jsonb_build_object('batch',to_jsonb(b),'files',(select coalesce(jsonb_agg(to_jsonb(f) order by id),'[]'::jsonb) from public.reading_files f where batch_id=r.batch_id),'rows',(select coalesce(jsonb_agg(to_jsonb(x) order by ord),'[]'::jsonb) from public.reading_rows x where batch_id=r.batch_id));
  if md5(data::text)<>r.fingerprint then raise exception 'archive_changed';end if;
  update public.reading_files set archived_digest=md5(source_b64),source_b64='',archived_at=now() where batch_id=r.batch_id;get diagnostics affected=row_count;
  update public.reading_batches set archived_digest=md5(coalesce(source_b64,'')),source_b64=null,archived_at=now() where id=r.batch_id;
 end if;
 update m2_ops.archive_receipts set consumed_at=now() where id=r.id;
 insert into public.audit_log(table_name,record_id,action,actor_id,new_row) values('cold_archive',r.id::text,'update',public.current_employee_id(),jsonb_build_object('kind',r.kind,'count',affected,'batch_id',r.batch_id));
 return affected;
end $$;

create or replace function public.restore_reading_archive(p_archive jsonb) returns integer
language plpgsql security definer set search_path=public as $$
declare b public.reading_batches%rowtype; f public.reading_files%rowtype; v jsonb; batch uuid; count_files integer:=0;
begin
 if not public.is_manager() then raise exception 'not_allowed' using errcode='42501';end if;
 if p_archive->>'app'<>'mukhayyam2' or p_archive->>'kind'<>'reading' or p_archive->>'version'<>'1' then raise exception 'invalid_archive';end if;
 batch:=(p_archive#>>'{data,batch,id}')::uuid;
 select * into b from public.reading_batches where id=batch for update;
 if b.archived_at is null then raise exception 'invalid_archive';end if;
 if md5(coalesce(p_archive#>>'{data,batch,source_b64}','')) is distinct from b.archived_digest then raise exception 'invalid_archive';end if;
 for f in select * from public.reading_files where batch_id=batch for update loop
  select x into v from jsonb_array_elements(p_archive#>'{data,files}') x where x->>'id'=f.id::text;
  if v is null or md5(coalesce(v->>'source_b64','')) is distinct from f.archived_digest then raise exception 'invalid_archive';end if;
  update public.reading_files set source_b64=v->>'source_b64',archived_at=null,archived_digest=null where id=f.id;
  count_files:=count_files+1;
 end loop;
 update public.reading_batches set source_b64=p_archive#>>'{data,batch,source_b64}',archived_at=null,archived_digest=null where id=batch;
 return count_files;
end $$;

do $$ declare f text; begin foreach f in array array['storage_overview()','prepare_cold_archive(text,uuid)','finish_cold_archive(uuid)','restore_reading_archive(jsonb)'] loop
 execute 'revoke all on function public.'||f||' from public,anon';
 execute 'grant execute on function public.'||f||' to authenticated';
end loop;end $$;

-- Never multiply file bodies or authentication credentials into change snapshots.
create or replace function public.audit_row() returns trigger
language plpgsql security definer set search_path=public as $$
declare o jsonb:=case when tg_op<>'INSERT' then to_jsonb(old) end;
 n jsonb:=case when tg_op<>'DELETE' then to_jsonb(new) end;
 private_keys text[]:=array['source_b64','link_token','token','pin','password','encrypted_password','auth_user_id'];
 ref text:=coalesce(coalesce(n,o)->>'id',coalesce(n,o)->>'seal_no');
begin
 if tg_op='UPDATE' and (o-'updated_at')=(n-'updated_at') then return new;end if;
 if tg_table_name='attendance_points' then private_keys:=private_keys||'code'::text;end if;
 insert into public.audit_log(table_name,record_id,action,actor_id,old_row,new_row)
 values(tg_table_name,ref,lower(tg_op),public.current_employee_id(),o-private_keys,n-private_keys);
 return coalesce(new,old);
end $$;

-- ===================== 20261030000039_attendance_office_network.sql =====================

-- =====================================================================
--  نظام مخيم 2: الحضور بالـQR بينفتح بس من إنترنت المكتب
-- =====================================================================
-- The manager, sitting on the office Wi-Fi, approves its public address (the one the server sees). A scan
-- that comes from another address (mobile data, home) is refused. Several addresses are allowed (a second
-- line). People marked «يسجّل من أي مكان» (field staff) skip the network and place checks.

alter table public.attendance_points add column if not exists allowed_ips text[] not null default '{}';
alter table public.attendance_points drop constraint if exists attendance_points_ips_few;
alter table public.attendance_points add constraint attendance_points_ips_few check (cardinality(allowed_ips) <= 5);
alter table public.employees add column if not exists punch_anywhere boolean not null default false;

-- The caller's public address, as the edge in front of the database reports it: Cloudflare's own
-- header first (a client cannot set it), then the proxy's.
create or replace function public.client_ip() returns text
language plpgsql stable set search_path = public as $$
declare
  h json;
  v text;
begin
  begin
    h := nullif(current_setting('request.headers', true), '')::json;
  exception when others then
    return null;
  end;
  if h is null then return null; end if;
  v := coalesce(nullif(btrim(h ->> 'cf-connecting-ip'), ''), nullif(btrim(h ->> 'x-real-ip'), ''), nullif(btrim(split_part(coalesce(h ->> 'x-forwarded-for', ''), ',', 1)), ''));
  return v;
end $$;
revoke execute on function public.client_ip() from public, anon;
grant execute on function public.client_ip() to authenticated;

-- The manager, on the office network, adds the address the server sees to the allowed list.
create or replace function public.attendance_office_network_add(p_point smallint) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  v_ip text := public.client_ip();
  cur text[];
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if v_ip is null then raise exception 'no_ip'; end if;
  select allowed_ips into cur from public.attendance_points where id = p_point;
  if not found then raise exception 'bad_point'; end if;
  if not (v_ip = any (cur)) then
    if cardinality(cur) >= 5 then raise exception 'too_many'; end if;
    update public.attendance_points set allowed_ips = array_append(cur, v_ip) where id = p_point;
  end if;
  return jsonb_build_object('ip', v_ip, 'ips', (select allowed_ips from public.attendance_points where id = p_point));
end $$;

-- What the server sees of the caller now (to check before approving).
create or replace function public.attendance_my_ip() returns text
language sql stable security definer set search_path = public as $$
  select case when public.is_manager() then public.client_ip() end
$$;

-- Field staff: allowed to scan from anywhere.
create or replace function public.admin_set_punch_anywhere(p_id uuid, p_value boolean) returns void
language plpgsql security definer set search_path = public as $$
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  update public.employees set punch_anywhere = coalesce(p_value, false) where id = p_id;
  if not found then raise exception 'missing'; end if;
end $$;

revoke execute on function public.attendance_office_network_add(smallint), public.attendance_my_ip(), public.admin_set_punch_anywhere(uuid, boolean) from public, anon;
grant execute on function public.attendance_office_network_add(smallint), public.attendance_my_ip(), public.admin_set_punch_anywhere(uuid, boolean) to authenticated;

-- The scan: the network (and the place) are checked unless this person may scan from anywhere.
create or replace function public.attendance_punch(
  p_point text, p_token text,
  p_lat double precision default null, p_lng double precision default null, p_acc double precision default null,
  p_peek boolean default false
) returns jsonb
language plpgsql security definer set search_path = public, extensions as $$
declare
  v_point smallint := public.attendance_point_id(p_point);
  pt public.attendance_points;
  d public.attendance_devices;
  e public.employees;
  v_last public.attendance_punches;
  v_kind public.punch_kind;
  v_day_start timestamptz := (date_trunc('day', now() at time zone 'Asia/Gaza')) at time zone 'Asia/Gaza';
  v_stay constant interval := interval '60 minutes';
  v_dist double precision;
  v_scans integer;
  v_status text := 'recorded';
  v_wait timestamptz;
begin
  if v_point is null then raise exception 'bad_point'; end if;
  select * into pt from public.attendance_points where id = v_point;
  select * into d from public.attendance_devices
    where token_hash = encode(digest(coalesce(p_token, ''), 'sha256'), 'hex') and revoked_at is null;
  if not found then raise exception 'unknown_device'; end if;
  select * into e from public.employees where id = d.employee_id;
  if not (e.is_active and e.tracks_attendance) then raise exception 'not_tracked'; end if;

  if not p_peek and not e.punch_anywhere then
    -- Only from the office network, once the manager approved it.
    if cardinality(pt.allowed_ips) > 0 and not (coalesce(public.client_ip(), '') = any (pt.allowed_ips)) then
      raise exception 'wrong_network';
    end if;
    -- And from the office place, when the manager has set where it is (the phone's own accuracy counts, up to 50 m).
    if pt.lat is not null then
      if p_lat is null or p_lng is null then raise exception 'need_location'; end if;
      v_dist := public.distance_m(pt.lat, pt.lng, p_lat, p_lng);
      if v_dist - least(greatest(coalesce(p_acc, 0), 0), 50) > pt.radius_m then
        raise exception 'too_far:%', round(v_dist);
      end if;
    end if;
  end if;

  perform pg_advisory_xact_lock(hashtext(e.id::text));
  select * into v_last from public.attendance_punches
    where employee_id = e.id and at >= v_day_start order by at desc limit 1;
  select count(*) into v_scans from public.attendance_punches
    where employee_id = e.id and at >= v_day_start and method = 'qr';

  if found and v_last.kind = 'in' then v_kind := 'out'; else v_kind := 'in'; end if;
  if v_scans >= 2 then
    v_status := 'full';
  elsif v_last.at is not null and v_last.at > now() - interval '2 minutes' then
    v_status := 'repeat';
  elsif v_kind = 'out' and v_last.at > now() - v_stay then
    v_status := 'wait';
    v_wait := v_last.at + v_stay;
  end if;

  if v_status = 'recorded' and not p_peek then
    insert into public.attendance_punches (employee_id, kind, at, method, point_id)
      values (e.id, v_kind, now(), 'qr', v_point);
  elsif v_status = 'recorded' then
    v_status := 'ready';
  end if;
  if not p_peek then update public.attendance_devices set last_used_at = now() where id = d.id; end if;

  return jsonb_build_object(
    'name', e.full_name,
    'repeat', v_status = 'repeat',
    'status', v_status,
    'next', v_kind,
    'wait_until', v_wait,
    'punches', coalesce((
      select jsonb_agg(jsonb_build_object('kind', p.kind, 'at', p.at) order by p.at)
      from public.attendance_punches p where p.employee_id = e.id and p.at >= v_day_start), '[]'::jsonb)
  );
end $$;

revoke execute on function public.attendance_punch(text, text, double precision, double precision, double precision, boolean) from public;
grant execute on function public.attendance_punch(text, text, double precision, double precision, double precision, boolean) to anon, authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000040_shared_tasks_search.sql =====================

-- Shared tasks keep one order and one completion owned by the office.
alter table public.tasks add column if not exists assignee_ids uuid[] not null default '{}';
create index if not exists tasks_members on public.tasks using gin(assignee_ids);
create or replace function public.task_member_ids(p_primary uuid,p_members uuid[]) returns uuid[]
language sql immutable set search_path=public as $$
 select coalesce(array_agg(id order by ord),'{}'::uuid[]) from (
 select id,min(ord) ord from unnest(case when cardinality(p_members)>0 then p_members when p_primary is not null then array[p_primary] else '{}'::uuid[] end) with ordinality a(id,ord) where id is not null group by id) x
$$;
create or replace function public.tasks_guard() returns trigger
language plpgsql security definer set search_path = public as $$
declare
  acting uuid := nullif(current_setting('m2.acting_employee', true), '')::uuid;
  me uuid := coalesce(acting, public.current_employee_id());
  mgr boolean := acting is null and (public.is_manager() or public.has_page('tasks'));
  t timestamptz;
  members uuid[]; old_members uuid[]; members_changed boolean;
begin
  if tg_op='UPDATE' then
    old_members:=public.task_member_ids(old.assignee_id,old.assignee_ids);
    -- Old clients change only the primary technician; retain that contract.
    if new.assignee_id is distinct from old.assignee_id and new.assignee_ids is not distinct from old.assignee_ids then
      new.assignee_ids:=case when new.assignee_id is null then '{}'::uuid[] else array[new.assignee_id] end;
    end if;
  end if;
  members:=public.task_member_ids(new.assignee_id,new.assignee_ids);
  new.assignee_ids:=members;new.assignee_id:=members[1];
  members_changed:=tg_op='INSERT' or members is distinct from old_members;
  if cardinality(members)>20 then raise exception 'too_many_technicians';end if;
  if members_changed and exists(select 1 from unnest(members) as member(member_id) where not exists(select 1 from public.employees e where e.id=member.member_id and e.role='technician' and e.is_active and e.deleted_at is null)) then raise exception 'invalid_technician';end if;
  if tg_op = 'INSERT'  then
    new.created_by := coalesce(me, new.created_by);
    new.status := 'new';
    new.sent_at := null; new.seen_at := null; new.started_at := null;
    new.completed_at := null; new.cancelled_at := null;
    return new;
  end if;

  if not mgr then
    if me is null or not (me=any(old_members)) then
      raise exception 'This task is not assigned to you';
    end if;
    if cardinality(old_members)>1 then raise exception 'office_completes_shared';end if;
    if (new.task_type_id, new.assignee_id, new.assignee_ids, new.details, new.subscriber_name, new.subscriber_phone,
        new.zone_id, new.location_text, new.priority, new.expected_minutes, new.created_by, new.cancel_reason, new.link_token)
       is distinct from
       (old.task_type_id, old.assignee_id, old_members, old.details, old.subscriber_name, old.subscriber_phone,
        old.zone_id, old.location_text, old.priority, old.expected_minutes, old.created_by, old.cancel_reason, old.link_token) then
      raise exception 'A technician can only start, finish and add notes to a task';
    end if;
    if new.status is distinct from old.status and not (
         (old.status in ('new', 'sent') and new.status = 'seen')
      or (old.status in ('new', 'sent', 'seen') and new.status = 'in_progress')
      or (old.status = 'in_progress' and new.status = 'done')) then
      raise exception 'Invalid task step';
    end if;
  else
    if members_changed then
      if old.status not in ('new', 'sent', 'seen') then
        raise exception 'A started or closed task cannot be reassigned';
      end if;
      new.status := 'new';
      new.sent_at := null; new.seen_at := null;
      insert into public.task_events (task_id, event, actor_id, meta)
        values (new.id, 'reassigned', me, jsonb_build_object('from',old.assignee_id,'to',new.assignee_id,'from_members',old_members,'to_members',members));
    elsif new.status is distinct from old.status and not (
         (old.status = 'new' and new.status = 'sent')
      or (old.status in ('new', 'sent', 'seen', 'in_progress') and new.status = 'cancelled')
      -- A technician without a smartphone: the office marks the task done for him.
      or (old.status in ('new', 'sent', 'seen', 'in_progress') and new.status = 'done' and new.assignee_id is not null)) then
      raise exception 'The manager can send or cancel a task; the technician starts and finishes it';
    end if;
  end if;

  -- Server-owned times: copied from the old row unless this update is the step that sets them.
  if not members_changed then new.sent_at:=old.sent_at;new.seen_at:=old.seen_at;
  else new.sent_at:=null;new.seen_at:=null;end if;
  new.started_at := old.started_at; new.completed_at := old.completed_at; new.cancelled_at := old.cancelled_at;

  if new.status is distinct from old.status then
    t := public.event_time(new.recorded_offline, new.device_time, coalesce(old.started_at, old.sent_at, old.created_at));
    case new.status
      when 'sent' then
        new.sent_at := now();
      when 'seen' then
        new.seen_at := t;
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'seen', me, t, new.recorded_offline);
      when 'in_progress' then
        new.seen_at := coalesce(new.seen_at, t);
        new.started_at := t;
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'started', me, t, new.recorded_offline);
      when 'done' then
        new.started_at := coalesce(new.started_at, least(t, coalesce(old.seen_at, old.sent_at, t)));
        new.completed_at := greatest(t, new.started_at);
        insert into public.task_events (task_id, event, actor_id, at, recorded_offline) values (new.id, 'completed', me, new.completed_at, new.recorded_offline);
      when 'cancelled' then
        new.cancel_reason := nullif(btrim(coalesce(new.cancel_reason, '')), '');
        new.cancelled_at := now();
        insert into public.task_events (task_id, event, actor_id) values (new.id, 'cancelled', me);
      else
        null;
    end case;
  end if;
  return new;
end $$;



drop policy if exists tasks_read on public.tasks;
create policy tasks_read on public.tasks for select to authenticated using(public.is_manager() or public.has_page('tasks') or assignee_id=public.current_employee_id() or assignee_ids @> array[public.current_employee_id()]);
drop policy if exists tasks_update on public.tasks;
create policy tasks_update on public.tasks for update to authenticated using(public.is_manager() or public.has_page('tasks') or assignee_id=public.current_employee_id() or assignee_ids @> array[public.current_employee_id()]) with check(public.is_manager() or public.has_page('tasks') or assignee_id=public.current_employee_id() or assignee_ids @> array[public.current_employee_id()]);
drop policy if exists task_events_read on public.task_events;
create policy task_events_read on public.task_events for select to authenticated using(public.is_manager() or public.has_page('tasks') or exists(select 1 from public.tasks t where t.id=task_id and cardinality(public.task_member_ids(t.assignee_id,t.assignee_ids))<=1));
create or replace function public.task_link_view(p_token text) returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  t public.tasks;
begin
  select * into t from public.tasks where link_token = p_token;
  if not found then return null; end if;
  if cardinality(public.task_member_ids(t.assignee_id,t.assignee_ids))<=1 and t.status in ('new', 'sent') then
    perform set_config('m2.acting_employee', t.assignee_id::text, true);
    update public.tasks set status = 'seen' where id = t.id returning * into t;
    perform set_config('m2.acting_employee', '', true);
  end if;
  return jsonb_build_object(
    'number', t.number,
    'type', (select name from public.task_types where id = t.task_type_id),
    'assignee',(select string_agg(e.full_name,'، ' order by e.full_name) from public.employees e where e.id=any(public.task_member_ids(t.assignee_id,t.assignee_ids))),
    'shared',cardinality(public.task_member_ids(t.assignee_id,t.assignee_ids))>1,
    'details', t.details,
    'subscriber_name', t.subscriber_name,
    'subscriber_phone', t.subscriber_phone,
    'zone', (select name from public.zones where id = t.zone_id),
    'location', t.location_text,
    'priority', t.priority,
    'expected_minutes', t.expected_minutes,
    'status', t.status,
    'sent_at', t.sent_at,
    'started_at', t.started_at,
    'completed_at', t.completed_at,
    'completion_notes', t.completion_notes,
    -- The list to pick used materials from, and what was recorded for this task.
    'items', case when t.status in ('done', 'cancelled') then '[]'::jsonb else coalesce((
      select jsonb_agg(jsonb_build_object('id', i.id, 'name', i.name, 'unit', i.unit) order by i.sort_order, i.id)
      from public.stock_items i where i.is_active), '[]'::jsonb) end,
    'materials', coalesce((
      select jsonb_agg(jsonb_build_object('name', i.name, 'unit', i.unit, 'qty', m.qty) order by m.created_at)
      from public.stock_moves m join public.stock_items i on i.id = m.item_id
      where m.task_id = t.id and m.kind = 'out'), '[]'::jsonb)
  );
end $$;

-- Only the office can send a shared order from the subscription. General bulk SMS remains manager-only.
create table if not exists m2_ops.shared_sms_requests(request_id uuid primary key,task_id uuid not null references public.tasks(id) on delete cascade,actor_id uuid not null references public.employees(id),members uuid[] not null,result jsonb not null,created_at timestamptz not null default now());
revoke all on m2_ops.shared_sms_requests from public,anon,authenticated;
create or replace function public.task_sms_units(p_text text) returns integer
language sql immutable set search_path=public as $$ select coalesce(sum(case when ascii(ch)>65535 then 2 else 1 end),0)::integer from regexp_split_to_table(coalesce(p_text,''),'') ch where ch<>'' $$;
create or replace function public.task_sms_trim(p_text text) returns text
language plpgsql immutable set search_path=public as $$ declare t text:=coalesce(p_text,'');begin while public.task_sms_units(t)>70 loop t:=left(t,length(t)-1);end loop;return t;end $$;
create or replace function public.shared_task_sms_text(p_task uuid) returns text
language plpgsql stable set search_path=public as $$
declare t public.tasks%rowtype; head text;who text;place text;msg text;
begin
 select * into t from public.tasks where id=p_task;if not found then return null;end if;
 head:=case t.priority when 'emergency' then 'طارئ ' when 'urgent' then 'مستعجل ' else '' end||'مهمة مشتركة '||t.number||': '||(select name from public.task_types where id=t.task_type_id);
 who:=array_to_string((regexp_split_to_array(btrim(coalesce(t.subscriber_name,'')),E'\\s+'))[1:2],' ');
 place:=concat_ws(' ',(select name from public.zones where id=t.zone_id),nullif(btrim(t.location_text),''));
 msg:=concat_ws(' · ',head,nullif(who,''),nullif(t.subscriber_phone,''),nullif(place,''),nullif(btrim(t.details),''));if public.task_sms_units(msg)<=70 then return msg;end if;
 msg:=concat_ws(' · ',head,nullif(who,''),nullif(t.subscriber_phone,''),nullif(place,''));if public.task_sms_units(msg)<=70 then return msg;end if;
 msg:=concat_ws(' · ',head,nullif(who,''),nullif(t.subscriber_phone,''));if public.task_sms_units(msg)<=70 then return msg;end if;
 return public.task_sms_trim(concat_ws(' · ',head,nullif(t.subscriber_phone,'')));
end $$;
drop function if exists public.task_send_shared_sms(uuid,uuid);
create or replace function public.task_send_shared_sms(p_task uuid,p_request uuid,p_members uuid[]) returns jsonb
language plpgsql security definer set search_path=public,m2_ops as $$
declare t public.tasks%rowtype;who uuid:=public.current_employee_id();members uuid[];e public.employees%rowtype;sms_body text;previous m2_ops.shared_sms_requests%rowtype;code text;ok boolean;sent integer:=0;already integer:=0;failed jsonb:='[]';result jsonb;cfg m2_ops.sms_config;
begin
 if who is null or not (public.is_manager() or public.has_page('tasks')) then raise exception 'not_allowed' using errcode='42501';end if;
 if p_request is null then raise exception 'bad_request';end if;
 perform pg_advisory_xact_lock(hashtextextended('m2-shared-sms:'||p_request::text,0));
 select * into previous from m2_ops.shared_sms_requests where request_id=p_request;
 if found then
  if previous.task_id<>p_task or previous.actor_id<>who or previous.members is distinct from p_members then raise exception 'bad_request';end if;
  return previous.result;
 end if;
 select * into t from public.tasks where id=p_task for update;
 if not found or t.status in ('done','cancelled') then raise exception 'task_closed';end if;
 members:=public.task_member_ids(t.assignee_id,t.assignee_ids);
 if members is distinct from p_members then raise exception 'assignment_changed';end if;
 if cardinality(members)<2 or cardinality(members)>20 then raise exception 'not_shared';end if;
 if exists(select 1 from unnest(members) as member(member_id) where not exists(select 1 from public.employees x where x.id=member.member_id and x.role='technician' and x.is_active and x.deleted_at is null and x.phone ~ '^05[0-9]{8}$')) then raise exception 'missing_technician_phone';end if;
 perform 1 from public.employees where id=any(members) for share;
 sms_body:=public.shared_task_sms_text(p_task);
 select * into cfg from m2_ops.sms_config where id=1;
 foreach who in array members loop
  select * into e from public.employees where id=who;
  if exists(select 1 from public.outgoing_messages m where m.task_id=p_task and m.channel='sms' and m.provider='hotsms' and m.status='sent' and m.to_phone=e.phone and m.body=sms_body) then already:=already+1;continue;end if;
  code:=m2_ops.hotsms('sendbulksms.php',jsonb_build_object('sender',coalesce(cfg.sender,'AF Camp2'),'mobile','972'||substr(e.phone,2),'type','2','text',sms_body));
  ok:=coalesce(code like '1001%',false);
  insert into public.outgoing_messages(task_id,channel,to_phone,body,status,provider,provider_ref,error,sent_at) values(p_task,'sms',e.phone,sms_body,case when ok then 'sent' else 'failed' end::public.message_status,'hotsms',code,case when ok then null else coalesce(code,'unknown') end,case when ok then now() end);
  if ok then sent:=sent+1;else failed:=failed||jsonb_build_object('phone',e.phone,'code',coalesce(code,'unknown'));end if;
 end loop;
 result:=jsonb_build_object('sent',sent,'already',already,'failed',failed,'body',sms_body);
 delete from m2_ops.shared_sms_requests where created_at<now()-interval '30 days';
 insert into m2_ops.shared_sms_requests(request_id,task_id,actor_id,members,result) values(p_request,p_task,public.current_employee_id(),members,result);
 return result;
end $$;

-- Search all authorized task history; it never indexes private task links.
create or replace function public.task_search_fold(p_text text) returns text
language sql immutable set search_path=public as $$
 select btrim(regexp_replace(translate(lower(regexp_replace(coalesce(p_text,''),'[ً-ْـ]','','g')),'أإآٱةىؤئ٠١٢٣٤٥٦٧٨٩۰۱۲۳۴۵۶۷۸۹','ااااهيوي01234567890123456789'),'[[:space:]]+',' ','g'))
$$;
create or replace function public.task_search(p_term text,p_offset integer default 0,p_limit integer default 50) returns setof public.tasks
language sql stable set search_path=public as $$
 with directory as materialized (select id,full_name from public.employee_directory())
 select t.* from public.tasks t left join public.task_types ty on ty.id=t.task_type_id left join public.zones z on z.id=t.zone_id
 where length(public.task_search_fold(p_term)) between 1 and 160 and not exists(
 select 1 from unnest(regexp_split_to_array(public.task_search_fold(p_term),' ')) q where strpos(public.task_search_fold(concat_ws(' ','مهمة رقم #'||t.number::text,t.subscriber_name,t.subscriber_phone,t.details,t.completion_notes,t.cancel_reason,t.location_text,ty.name,z.name,(select string_agg(e.full_name,' ') from directory e where e.id=any(public.task_member_ids(t.assignee_id,t.assignee_ids))),case when cardinality(public.task_member_ids(t.assignee_id,t.assignee_ids))>1 then 'مهمة مشتركة' else '' end,case t.status when 'done' then 'أُنجزت منجزة' when 'cancelled' then 'ألغيت ملغية' when 'in_progress' then 'قيد التنفيذ' when 'sent' then 'أرسلت' else 'لم ترسل' end)),q)=0)
 order by t.number desc,t.id limit greatest(1,least(coalesce(p_limit,50),100)) offset greatest(0,coalesce(p_offset,0))
$$;
do $$ declare f text;begin foreach f in array array['task_sms_units(text)','task_sms_trim(text)','task_member_ids(uuid,uuid[])','shared_task_sms_text(uuid)','task_send_shared_sms(uuid,uuid,uuid[])','task_search_fold(text)','task_search(text,integer,integer)'] loop
 execute 'revoke all on function public.'||f||' from public,anon';execute 'grant execute on function public.'||f||' to authenticated';
end loop;end $$;
notify pgrst,'reload schema';

-- The day selected by the office also selects the matrix and its printed statement.
create or replace function public.tasks_for_day(p_day date,p_offset integer default 0,p_limit integer default 500) returns setof public.tasks
language sql stable set search_path=public as $$
 select t.* from public.tasks t where p_day in ((t.created_at at time zone 'Asia/Gaza')::date,(t.completed_at at time zone 'Asia/Gaza')::date,(t.cancelled_at at time zone 'Asia/Gaza')::date)
 order by t.number desc,t.id limit greatest(1,least(coalesce(p_limit,500),1000)) offset greatest(0,coalesce(p_offset,0))
$$;
revoke all on function public.tasks_for_day(date,integer,integer) from public,anon;
grant execute on function public.tasks_for_day(date,integer,integer) to authenticated;

-- ===================== 20261030000041_server_alerts.sql =====================

-- =====================================================================
--  نظام مخيم 2: تنبيهات من الخادم برسالة SMS (حتى لو ما حدا فاتح الموقع)
-- =====================================================================
-- Every 30 minutes the database itself looks for what needs the manager and texts the chosen phones from
-- the company's SMS subscription (the same login as Settings › الرسائل):
--   · yesterday's generation report or distribution sheet not sent by the late time (report_late_warn)
--   · tasks past their expected time (each task once)
--   · diesel running out (fewer days left than fuel_days_danger), once per report
--   · the nightly backup not taken for more than a day and a half
-- Each alert goes out once (m2_ops.alerts_sent). Off until the manager turns it on.

alter table public.app_settings add column if not exists alert_sms boolean not null default false;
alter table public.app_settings add column if not exists alert_phones text[] not null default '{}';

create table if not exists m2_ops.alerts_sent (
  kind text not null,
  ref text not null,
  sent_at timestamptz not null default now(),
  primary key (kind, ref)
);

-- What would be sent right now (texts not yet sent), without sending. The check job and the settings
-- preview both use it.
create or replace function m2_ops.alerts_due() returns table (kind text, ref text, body text)
language plpgsql stable security definer set search_path = public as $$
declare
  s public.app_settings;
  now_gaza timestamp := now() at time zone 'Asia/Gaza';
  today date := (now() at time zone 'Asia/Gaza')::date;
  yday date := (now() at time zone 'Asia/Gaza')::date - 1;
  rep record;
  remaining numeric;
  daily numeric;
  late_list text;
  late_refs text[];
  last_backup timestamptz;
begin
  select * into s from public.app_settings limit 1;
  if s is null then return; end if;

  -- 1) Yesterday's papers, once the late time has passed today.
  if now_gaza::time >= s.report_late_warn then
    if not exists (select 1 from public.site_reports r where r.report_date = yday and r.status in ('submitted', 'approved'))
       and not exists (select 1 from m2_ops.alerts_sent a where a.kind = 'late_generation' and a.ref = yday::text) then
      kind := 'late_generation'; ref := yday::text;
      body := 'مخيم 2: تقرير التوليد ليوم ' || to_char(yday, 'DD/MM') || ' ما وصل لهلأ.';
      return next;
    end if;
    if not exists (select 1 from public.distribution_sheets d where d.sheet_date = yday and d.status in ('submitted', 'approved'))
       and not exists (select 1 from m2_ops.alerts_sent a where a.kind = 'late_distribution' and a.ref = yday::text) then
      kind := 'late_distribution'; ref := yday::text;
      body := 'مخيم 2: كشف التوزيع ليوم ' || to_char(yday, 'DD/MM') || ' ما وصل لهلأ.';
      return next;
    end if;
  end if;

  -- 2) Tasks past their time (sent, still open), each one once; one text for all the new ones.
  select string_agg('#' || t.number, '، ' order by t.number), array_agg(t.id::text)
    into late_list, late_refs
    from public.tasks t
   where t.status in ('sent', 'seen', 'in_progress')
     and coalesce(t.sent_at, t.created_at) + make_interval(mins => t.expected_minutes) < now()
     and coalesce(t.sent_at, t.created_at) > now() - interval '3 days'
     and not exists (select 1 from m2_ops.alerts_sent a where a.kind = 'late_task' and a.ref = t.id::text);
  if late_refs is not null then
    kind := 'late_task'; ref := array_to_string(late_refs, ',');
    body := 'مخيم 2: ' || case when cardinality(late_refs) = 1 then 'مهمة تجاوزت وقتها: ' else cardinality(late_refs) || ' مهام تجاوزت وقتها: ' end
            || left(late_list, 120);
    return next;
  end if;

  -- 3) Diesel: the last sent report, at the average daily use of the last seven reports.
  select r.id, r.report_date into rep
    from public.site_reports r where r.status in ('submitted', 'approved') order by r.report_date desc limit 1;
  if rep.id is not null and not exists (select 1 from m2_ops.alerts_sent a where a.kind = 'fuel_low' and a.ref = rep.report_date::text) then
    select sum(f.closing_balance) into remaining from public.site_report_fuel f where f.report_id = rep.id and f.closing_balance is not null;
    select avg(c) into daily from (
      select sum(f.consumption) c from public.site_reports r join public.site_report_fuel f on f.report_id = r.id
       where r.status in ('submitted', 'approved') and r.report_date <= rep.report_date
       group by r.report_date order by r.report_date desc limit 7) x
     where c > 0;
    if remaining is not null and daily > 0 and remaining / daily < s.fuel_days_danger then
      kind := 'fuel_low'; ref := rep.report_date::text;
      body := 'مخيم 2: السولار قرب يخلص. الباقي ' || round(remaining) || ' لتر، بيكفي تقريباً ' || round(remaining / daily, 1) || ' يوم.';
      return next;
    end if;
  end if;

  -- 4) The nightly copy (only once one was ever taken, so a new system does not warn).
  select max(b.taken_at) into last_backup from public.backups b;
  if last_backup is not null and last_backup < now() - interval '36 hours'
     and not exists (select 1 from m2_ops.alerts_sent a where a.kind = 'backup' and a.ref = today::text) then
    kind := 'backup'; ref := today::text;
    body := 'مخيم 2: النسخة الاحتياطية التلقائية ما انعملت من ' || to_char(last_backup at time zone 'Asia/Gaza', 'DD/MM') || '. افحصوها.';
    return next;
  end if;
end $$;
revoke all on function m2_ops.alerts_due() from public;

-- The job: sends what is due to the chosen phones and remembers it. Nothing when it is off.
create or replace function m2_ops.alerts_run() returns integer
language plpgsql security definer set search_path = public as $$
declare
  s public.app_settings;
  cfg m2_ops.sms_config;
  a record;
  ph text;
  code text;
  ok boolean;
  n integer := 0;
begin
  select * into s from public.app_settings limit 1;
  if s is null or not s.alert_sms or cardinality(s.alert_phones) = 0 then return 0; end if;
  select * into cfg from m2_ops.sms_config where id = 1;
  if cfg.user_name is null then return 0; end if;
  for a in select * from m2_ops.alerts_due() loop
    ok := false;
    foreach ph in array s.alert_phones loop
      code := m2_ops.hotsms('sendbulksms.php', jsonb_build_object(
        'sender', coalesce(cfg.sender, 'AF Camp2'), 'mobile', '972' || substr(ph, 2), 'type', '2', 'text', a.body));
      insert into public.outgoing_messages (channel, to_phone, body, status, provider, provider_ref, error, sent_at)
      values ('sms', ph, a.body, case when code like '1001%' then 'sent' else 'failed' end::public.message_status,
              'hotsms', code, case when code like '1001%' then null else code end, case when code like '1001%' then now() end);
      ok := ok or code like '1001%';
    end loop;
    -- Remembered only once it went out, so a failed send is tried again next time.
    if ok then
      insert into m2_ops.alerts_sent (kind, ref)
        select a.kind, r from unnest(case when a.kind = 'late_task' then string_to_array(a.ref, ',') else array[a.ref] end) r
        on conflict do nothing;
      n := n + 1;
    end if;
  end loop;
  delete from m2_ops.alerts_sent where sent_at < now() - interval '30 days';
  return n;
end $$;
revoke all on function m2_ops.alerts_run() from public;

-- Settings › الرسائل: turn on/off and the phones (up to 3).
create or replace function public.alerts_set(p_on boolean, p_phones text[]) returns void
language plpgsql security definer set search_path = public as $$
declare
  phones text[] := array(select distinct btrim(x) from unnest(coalesce(p_phones, '{}')) x where btrim(x) <> '');
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if cardinality(phones) > 3 then raise exception 'too_many'; end if;
  if exists (select 1 from unnest(phones) x where x !~ '^05[0-9]{8}$') then raise exception 'bad_phone'; end if;
  if p_on and cardinality(phones) = 0 then raise exception 'no_phone'; end if;
  update public.app_settings set alert_sms = p_on, alert_phones = phones where id;
end $$;

-- What the screen shows: on/off, the phones, what would go out now, and whether the nightly jobs run.
create or replace function public.alerts_info() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s public.app_settings;
  jobs jsonb := '[]'::jsonb;
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  select * into s from public.app_settings limit 1;
  -- pg_cron is on Supabase; a bare test database has none.
  if to_regclass('cron.job') is not null then
    execute $q$
      select coalesce(jsonb_agg(jsonb_build_object(
               'name', j.jobname, 'active', j.active,
               'last_at', d.start_time, 'last_status', d.status, 'last_error', left(d.return_message, 200))), '[]'::jsonb)
        from cron.job j
        left join lateral (select start_time, status, return_message from cron.job_run_details x
                            where x.jobid = j.jobid order by x.start_time desc limit 1) d on true
       where j.jobname like 'm2-%'
    $q$ into jobs;
  end if;
  return jsonb_build_object(
    'on', coalesce(s.alert_sms, false),
    'phones', to_jsonb(coalesce(s.alert_phones, '{}')),
    'due', (select coalesce(jsonb_agg(jsonb_build_object('kind', d.kind, 'body', d.body)), '[]'::jsonb) from m2_ops.alerts_due() d),
    'last_backup', (select max(taken_at) from public.backups),
    'jobs', jobs,
    'cron', to_regclass('cron.job') is not null
  );
end $$;

-- «جرّب»: one test text to the chosen phones.
create or replace function public.alerts_test() returns jsonb
language plpgsql security definer set search_path = public as $$
declare
  s public.app_settings;
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  select * into s from public.app_settings limit 1;
  if cardinality(s.alert_phones) = 0 then raise exception 'no_phone'; end if;
  return public.sms_send(s.alert_phones, 'مخيم 2: تجربة التنبيهات. إذا وصلتك هالرسالة، التنبيهات شغالة.');
end $$;

revoke execute on function public.alerts_set(boolean, text[]), public.alerts_info(), public.alerts_test() from anon, public;
grant execute on function public.alerts_set(boolean, text[]), public.alerts_info(), public.alerts_test() to authenticated;

-- Every 30 minutes, with Supabase's scheduler.
do $$
begin
  if exists (select 1 from pg_extension where extname = 'pg_cron') then
    perform cron.unschedule(jobid) from cron.job where jobname = 'm2-alerts';
    perform cron.schedule('m2-alerts', '*/30 * * * *', 'select m2_ops.alerts_run()');
  else
    raise notice 'pg_cron is not available here: alerts are not scheduled';
  end if;
end $$;

notify pgrst, 'reload schema';

-- ===================== 20261030000042_fuel_suppliers_maintenance_plan.sql =====================

-- =====================================================================
--  نظام مخيم 2: مورّد وسعر السولار الوارد، وجدول صيانة المولدات
-- =====================================================================
-- Fuel received on a day now carries who supplied it and the price per liter (both optional), next to the
-- shipment number it already had. The reports list every shipment and flag a repeated or missing number.
alter table public.site_report_fuel add column if not exists supplier text;
alter table public.site_report_fuel add column if not exists unit_price numeric check (unit_price is null or (unit_price >= 0 and unit_price < 1000));

-- How often each kind of maintenance is due, by running hours or by days (whichever is set). Oil change
-- keeps its own two settings (oil_change_warn_hours / oil_change_due_hours).
alter table public.app_settings add column if not exists maintenance_plan jsonb not null default
  '{"oil_filter":{"hours":250},"fuel_filter":{"hours":500},"air_filter":{"hours":500},"cooling":{"days":30},"battery":{"days":60},"belt":{"days":90}}'::jsonb;

-- The manager edits the plan (Settings). Only known kinds, whole positive numbers.
create or replace function public.maintenance_plan_set(p_plan jsonb) returns void
language plpgsql security definer set search_path = public as $$
declare
  k text;
  v jsonb;
begin
  if not public.is_manager() then raise exception 'not_allowed' using errcode = '42501'; end if;
  if jsonb_typeof(p_plan) is distinct from 'object' then raise exception 'bad_plan'; end if;
  for k, v in select * from jsonb_each(p_plan) loop
    if k not in ('oil_filter', 'fuel_filter', 'air_filter', 'cooling', 'battery', 'belt', 'electrical') then raise exception 'bad_plan'; end if;
    if exists (select 1 from jsonb_each(v) x where x.key not in ('hours', 'days')
               or jsonb_typeof(x.value) <> 'number' or (x.value)::numeric <= 0 or (x.value)::numeric > 10000
               or (x.value)::numeric <> trunc((x.value)::numeric)) then
      raise exception 'bad_plan';
    end if;
  end loop;
  update public.app_settings set maintenance_plan = p_plan where id;
end $$;
revoke execute on function public.maintenance_plan_set(jsonb) from anon, public;
grant execute on function public.maintenance_plan_set(jsonb) to authenticated;

notify pgrst, 'reload schema';

-- ===================== 20261030000043_subscriber_profile.sql =====================

-- =====================================================================
--  نظام مخيم 2: ملف المشترك (مهامه وأختامه وقراءاته بمكان واحد)
-- =====================================================================
-- One call for one subscriber: the directory line(s), the tasks done for him (by name or phone), the seals
-- recorded on his name or board, and his meter readings week by week. Names are compared folded
-- (hamza, taa marbuta, ya, both digit alphabets, spaces), boards without spaces.
-- For the manager and whoever has the tasks page.

create or replace function public.subscriber_profile(p_name text, p_board text default null, p_phone text default null) returns jsonb
language plpgsql stable security definer set search_path = public as $$
declare
  n text := public.task_search_fold(p_name);
  b text := nullif(regexp_replace(public.task_search_fold(p_board), '\s+', '', 'g'), '');
  ph text := case when p_phone ~ '^05[0-9]{8}$' then p_phone end;
begin
  if not (public.is_manager() or public.has_page('tasks')) then raise exception 'not_allowed' using errcode = '42501'; end if;
  if length(n) < 2 then raise exception 'short_name'; end if;
  return jsonb_build_object(
    'directory', (
      select coalesce(jsonb_agg(jsonb_build_object('name', s.full_name, 'area', s.area, 'board', s.board, 'phone', s.phone) order by s.id), '[]'::jsonb)
        from (select * from public.subscribers s
               where public.task_search_fold(s.full_name) = n or (ph is not null and s.phone = ph) limit 5) s),
    'tasks', (
      select coalesce(jsonb_agg(x order by x->>'created_at' desc), '[]'::jsonb) from (
        select jsonb_build_object(
                 'id', t.id, 'number', t.number, 'type', ty.name, 'status', t.status, 'details', t.details,
                 'created_at', t.created_at, 'completed_at', t.completed_at, 'notes', t.completion_notes,
                 'who', (select string_agg(e.full_name, '، ') from public.employees e where e.id = any(public.task_member_ids(t.assignee_id, t.assignee_ids)))) x
          from public.tasks t left join public.task_types ty on ty.id = t.task_type_id
         where public.task_search_fold(t.subscriber_name) = n or (ph is not null and t.subscriber_phone = ph)
         order by t.created_at desc limit 60) q),
    'seals', (
      select coalesce(jsonb_agg(x order by x->>'used_on' desc nulls last), '[]'::jsonb) from (
        select jsonb_build_object('seal_no', s.seal_no, 'status', s.status, 'used_on', s.used_on, 'details', s.details, 'board', s.board_no,
                                  'who', (select e.full_name from public.employees e where e.id = s.technician_id)) x
          from public.seals s
         where s.status in ('used', 'damaged', 'lost')
           and ((b is not null and regexp_replace(public.task_search_fold(s.board_no), '\s+', '', 'g') = b)
             or (position(' ' in n) > 0 and strpos(public.task_search_fold(s.details), n) > 0))
         order by s.used_on desc nulls last limit 60) q),
    'readings', (
      select coalesce(jsonb_agg(x order by x->>'period_to' desc nulls last), '[]'::jsonb) from (
        select jsonb_build_object('week', rb.title, 'period_to', rb.period_to, 'code', r.code, 'board', r.board, 'prev', r.prev,
                                  'reading', r.reading, 'state', r.state, 'at', r.entered_at) x
          from public.reading_rows r join public.reading_batches rb on rb.id = r.batch_id
         where public.task_search_fold(r.subscriber) = n
           and (b is null or regexp_replace(public.task_search_fold(r.board), '\s+', '', 'g') = b or r.board = '')
         order by rb.period_to desc nulls last, rb.created_at desc limit 30) q)
  );
end $$;
revoke execute on function public.subscriber_profile(text, text, text) from anon, public;
grant execute on function public.subscriber_profile(text, text, text) to authenticated;

notify pgrst, 'reload schema';

